content.text:
      res.setHeader('Content-Type', mime[extname(file)] || 'application/octet-stream')
      res.setHeader('Cache-Control', url.searchParams.has('omgithub_live') ? 'no-store' : 'no-cache')
      const content = readFileSync(file)
      if (extname(file) === '.html' && url.searchParams.get('omgithub_live') === '1') {
        const html = content.toString()
        res.end(/<\/body\s*>/i.test(html) ? html.replace(/<\/body\s*>/i, `${livePreviewScript}</body>`) : html + livePreviewScript)
      } else res.end(content)
    } catch { res.writeHead(404); res.end('Not found') }
  })
  server.on('close', () => { stopWatching(); clearInterval(keepAlive); buildWatcher?.kill(); for (const client of clients) client.end() })
  server.listen(Number(process.env.PORT || 3000), '0.0.0.0')
  return server
}
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) await start()
import { startForCapture } from './capture-start.mjs'
import captures from './wip-screenshots.cjs'
import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
captures.instrument({ chromium })
const config = JSON.parse(readFileSync(join(runtime, process.platform === 'darwin' ? 'metal.json' : 'linux.json'), 'utf8'))
if (process.platform === 'linux') process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const url = process.env.CAPTURE_URL, output = process.env.CAPTURE_DIR
if (!url || !output) throw new Error('Set CAPTURE_URL and CAPTURE_DIR.')
mkdirSync(output, { recursive: true })
const transient = error => { throw Object.assign(error, { exitCode: 75 }) }
let browser
try {
  browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 }).catch(transient)
  for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
    const page = await browser.newPage({ viewport: { width, height } }).catch(transient)
    page.setDefaultTimeout(30000)
    const failures = []
    page.on('pageerror', error => { console.error(error.message); failures.push(error.message) })
    page.on('response', response => { if (response.status() >= 400 && new URL(response.url()).origin === new URL(url).origin) failures.push(`HTTP ${response.status()}: ${response.url()}`) })
    const response = await page.goto(url, { waitUntil: 'load', timeout: 45000 }).catch(transient)
    if (!response?.ok()) throw Object.assign(new Error(`HTTP ${response?.status()} loading preview`), { exitCode: !response || [408, 429, 500, 502, 503, 504].includes(response.status()) ? 75 : 1 })
    await page.locator(process.env.CAPTURE_READY_SELECTOR || 'body').waitFor({ state: 'visible' })
    await page.waitForFunction(() => document.fonts.status === 'loaded')
    const start = await startForCapture(page, {
      enabled: process.env.CAPTURE_AUTO_START !== 'false',
      selector: process.env.CAPTURE_START_SELECTOR || ''
    })
    console.log(`Capture ${name}: auto-start ${start.clicked ? 'clicked' : start.reason}`)
    await page.waitForTimeout(1000)
    await page.screenshot({ path: join(output, `final-${name}.png`), timeout: 30000 }).catch(error => {
      if (error.name === 'TimeoutError' || !browser.isConnected()) transient(error)
      throw error
    })
    if (process.env.CAPTURE_STRICT === '1' && failures.length) throw new Error(`Published build failed: ${failures.join('; ')}`)
    await page.close()
  }
} catch (error) { console.error(error); process.exitCode = error.exitCode || 1 }
finally { await browser?.close().catch(error => { console.error(error); process.exitCode ||= 75 }) }

input.content:
:root{
  --red:#c8372d;
  --red-hi:#ff5b41;
  --gold:#e3bf78;
  --ink:#07090b;
  --ink-2:#0d1115;
  --panel:rgba(11,15,19,.82);
  --panel-2:rgba(16,21,26,.9);
  --line:rgba(255,255,255,.12);
  --line-soft:rgba(255,255,255,.07);
  --text:#eef3f7;
  --muted:#93a0ab;
  --green:#63d69b;
  --cyan:#6fd6e8;
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;padding:0;height:100%;overflow:hidden;background:var(--ink);color:var(--text);
  font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  overscroll-behavior:none;touch-action:none}
body{position:fixed;inset:0;user-select:none;-webkit-user-select:none}
button{font:inherit;color:inherit;border:0;background:none;cursor:pointer}
button:focus-visible{outline:2px solid var(--red-hi);outline-offset:3px}
kbd{font:600 11px/1 ui-monospace,SFMono-Regular,Menlo,monospace;background:rgba(255,255,255,.1);
  border:1px solid rgba(255,255,255,.16);border-bottom-color:rgba(0,0,0,.5);border-radius:4px;padding:4px 5px;color:#dfe7ee}
.hidden{display:none!important}

#app{position:fixed;inset:0;isolation:isolate}
#scene{position:absolute;inset:0;width:100%;height:100%;display:block;outline:none}
#vignette{position:absolute;inset:0;pointer-events:none;z-index:2;
  background:radial-gradient(ellipse at 50% 48%,transparent 42%,rgba(0,0,0,.22) 72%,rgba(0,0,0,.72) 100%)}
#vignette.danger{box-shadow:inset 0 0 140px 30px rgba(190,24,16,.55)}
#speedlines{position:absolute;inset:0;pointer-events:none;z-index:3;opacity:0;transition:opacity .18s;
  background:repeating-conic-gradient(from 0deg at 50% 50%,rgba(255,255,255,.16) 0deg .35deg,transparent .35deg 7deg);
  mask-image:radial-gradient(circle at center,transparent 0 32%,#000 75%);
  -webkit-mask-image:radial-gradient(circle at center,transparent 0 32%,#000 75%)}
#speedlines.on{opacity:.55;animation:spinlines .6s linear infinite}
@keyframes spinlines{to{transform:rotate(2.2deg)}}
#hitflash{position:absolute;inset:0;pointer-events:none;z-index:4;opacity:0;background:radial-gradient(circle,rgba(255,70,45,0) 30%,rgba(200,25,15,.55) 100%);transition:opacity .12s}
#fps-badge{position:absolute;z-index:60;right:calc(14px + var(--safe-r));bottom:calc(12px + var(--safe-b));
  font:600 11px/1 ui-monospace,monospace;color:#b8c6d1;background:rgba(0,0,0,.45);padding:5px 7px;border-radius:4px;letter-spacing:.08em}

/* ---------- SCREENS ---------- */
.screen{position:absolute;inset:0;z-index:20}
#boot{display:grid;place-items:center;background:
  radial-gradient(circle at 50% 30%,rgba(200,55,45,.16),transparent 42%),
  linear-gradient(180deg,#07090b,#0b0e12 60%,#07090b)}
.boot-inner{width:min(520px,88vw);text-align:center;padding:30px}
.boot-mark{width:74px;height:74px;margin:0 auto 18px;color:#e9eef4;filter:drop-shadow(0 0 26px rgba(200,55,45,.35))}
.boot-mark svg{width:100%;height:100%}
.boot-title{font:900 clamp(36px,7vw,58px)/1 "Arial Black","Arial Narrow",sans-serif;letter-spacing:.06em}
.boot-title span{color:var(--red-hi)}
.boot-sub{margin-top:12px;font:600 11px/1 ui-monospace,monospace;letter-spacing:.42em;color:var(--muted)}
.boot-track{height:3px;background:rgba(255,255,255,.1);margin:34px 0 10px;overflow:hidden}
#boot-bar{height:100%;width:2%;background:linear-gradient(90deg,var(--red),var(--red-hi),var(--gold));transition:width .25s ease}
#boot-status{font:500 11px/1.4 ui-monospace,monospace;color:#8c9aa5;letter-spacing:.12em}
.boot-tip{margin-top:42px;color:#6f7d88;font-size:12px;line-height:1.5;border-top:1px solid var(--line-soft);padding-top:16px}

/* ---------- MENU ---------- */
#menu{overflow:hidden;background:linear-gradient(90deg,rgba(5,7,9,.92) 0%,rgba(5,7,9,.72) 38%,rgba(5,7,9,.28) 65%,rgba(5,7,9,.55) 100%)}
.menu-shade{position:absolute;inset:0;pointer-events:none;background:
  linear-gradient(180deg,rgba(5,7,9,.9),transparent 22%,transparent 70%,rgba(5,7,9,.92)),
  radial-gradient(ellipse at 25% 55%,rgba(0,0,0,.5),transparent 60%)}
.menu-head{position:relative;z-index:3;display:flex;align-items:center;gap:16px;
  padding:calc(18px + var(--safe-t)) calc(28px + var(--safe-r)) 0 calc(28px + var(--safe-l))}
.brand{display:flex;align-items:center;gap:11px;margin-right:auto}
.brand-mark{width:34px;height:34px;color:#e9eef4}
.brand strong{display:block;font:900 15px/1 "Arial Black",sans-serif;letter-spacing:.12em}
.brand span{display:block;font:600 8px/1 ui-monospace,monospace;letter-spacing:.38em;color:var(--red-hi);margin-top:4px}
.profile-chip{display:flex;align-items:center;gap:10px;padding:7px 14px 7px 7px;border:1px solid var(--line);
  background:rgba(10,14,18,.55);backdrop-filter:blur(10px);border-radius:999px}
.profile-chip .avatar{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font:900 13px/1 "Arial Black";
  background:linear-gradient(145deg,#3a4650,#171d23);border:1px solid rgba(255,255,255,.18);color:var(--gold)}
.profile-chip b{display:block;font-size:11px;letter-spacing:.06em}
.profile-chip span{display:block;font-size:9px;color:var(--muted);margin-top:2px}
.coin-chip{display:flex;align-items:center;gap:7px;padding:9px 14px;border:1px solid rgba(227,191,120,.35);
  background:rgba(227,191,120,.08);border-radius:999px;font:700 12px/1 ui-monospace,monospace;color:var(--gold)}
.coin{font-size:14px}
.menu-main{position:relative;z-index:3;display:grid;grid-template-columns:minmax(420px,1fr) minmax(440px,.95fr);
  gap:clamp(28px,5vw,90px);align-items:center;height:calc(100% - 160px);padding:0 calc(5vw + var(--safe-r)) 0 calc(5vw + var(--safe-l))}
.hero-copy{max-width:680px;padding-bottom:2vh}
.eyebrow{display:flex;align-items:center;gap:9px;font:700 10px/1 ui-monospace,monospace;letter-spacing:.34em;color:#c4ced7}
.eyebrow i{width:26px;height:1px;background:var(--red-hi);box-shadow:0 0 12px var(--red-hi)}
h1{margin:18px 0 16px;font:900 clamp(58px,8.6vw,124px)/.82 "Arial Black","Arial Narrow",sans-serif;letter-spacing:-.02em;
  text-shadow:0 6px 50px rgba(0,0,0,.55)}
h1 span{display:block;color:transparent;-webkit-text-stroke:1.5px rgba(232,239,245,.55);position:relative;
  letter-spacing:.08em;font-size:.62em;margin-top:10px}
h1 span::after{content:"ODM COMBAT";position:absolute;right:2px;bottom:-20px;font:700 9px/1 ui-monospace,monospace;
  letter-spacing:.5em;color:var(--red-hi);-webkit-text-stroke:0}
.hero-copy>p{max-width:430px;color:#aab5be;font-size:clamp(12px,1.15vw,15px);line-height:1.65;margin:0 0 24px;text-shadow:0 2px 10px #000}
.hero-stats{display:flex;gap:clamp(20px,3vw,42px);padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);max-width:430px}
.hero-stats b{display:block;font:800 24px/1 "Arial Narrow",Arial,sans-serif;letter-spacing:.02em}
.hero-stats span{display:block;margin-top:6px;font:500 9px/1.2 ui-monospace,monospace;letter-spacing:.12em;color:var(--muted)}
.hero-actions{display:flex;gap:10px;margin-top:24px;flex-wrap:wrap}
.btn{position:relative;display:inline-flex;align-items:center;justify-content:center;gap:12px;height:48px;padding:0 22px;
  border:1px solid var(--line);border-radius:2px;font:700 11px/1 ui-monospace,monospace;letter-spacing:.16em;overflow:hidden;
  transition:transform .15s,border-color .15s,background .15s}
.btn:hover{transform:translateY(-1px);border-color:rgba(255,255,255,.3)}
.btn.primary{background:linear-gradient(100deg,#b52d24,#e04432);border-color:rgba(255,120,95,.55);box-shadow:0 10px 30px rgba(180,35,25,.28)}
.btn.primary:hover{background:linear-gradient(100deg,#c63429,#f04d39)}
.btn.primary span{font-size:10px}
.btn.ghost{background:rgba(255,255,255,.035)}
.btn.gold{background:rgba(227,191,120,.13);border-color:rgba(227,191,120,.4);color:var(--gold)}
.btn.danger{border-color:rgba(200,55,45,.5);color:#ff8d7c;background:rgba(200,55,45,.1)}
.btn:disabled{opacity:.38;cursor:not-allowed;transform:none}

.mode-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;align-content:center}
.mode-card{position:relative;display:grid;grid-template-columns:44px 1fr 20px;align-items:center;gap:13px;text-align:left;
  min-height:82px;padding:14px 15px;border:1px solid var(--line);background:linear-gradient(120deg,rgba(16,21,26,.78),rgba(10,13,17,.6));
  backdrop-filter:blur(9px);overflow:hidden;transition:transform .18s,border-color .18s,background .18s}
.mode-card::before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--red);transform:scaleY(0);transform-origin:bottom;transition:transform .2s}
.mode-card:hover{transform:translateY(-2px);border-color:rgba(255,255,255,.25);background:linear-gradient(120deg,rgba(26,32,39,.9),rgba(13,17,22,.72))}
.mode-card:hover::before{transform:scaleY(1)}
.mode-card.story::before{background:var(--red-hi)}
.mode-card.roam::before{background:var(--cyan)}
.mode-card.survival::before{background:#f0a24c}
.mode-card.training::before{background:var(--green)}
.mode-card.squad::before{background:#a98bf5}
.mode-card.arsenal::before{background:var(--gold)}
.mode-icon{width:44px;height:44px;display:grid;place-items:center;font-size:19px;border:1px solid var(--line-soft);background:rgba(255,255,255,.035)}
.mode-copy b{display:block;font:800 12px/1 "Arial Narrow",Arial,sans-serif;letter-spacing:.16em}
.mode-copy span{display:block;margin-top:6px;font-size:9.5px;line-height:1.35;color:var(--muted);letter-spacing:.03em}
.mode-go{font-size:15px;color:#5e6b76;transition:transform .2s,color .2s}
.mode-card:hover .mode-go{transform:translateX(3px);color:var(--red-hi)}
.menu-foot{position:absolute;z-index:3;left:calc(5vw + var(--safe-l));right:calc(5vw + var(--safe-r));bottom:calc(16px + var(--safe-b));
  display:flex;align-items:center;gap:22px;border-top:1px solid var(--line-soft);padding-top:13px;font-size:10px;color:#79858f}
.foot-hint{display:flex;gap:7px;align-items:center;flex-wrap:wrap}
.foot-hint kbd{font-size:9px;padding:3px 4px}
.foot-links{display:flex;gap:18px;margin-left:auto}
.foot-links button{font:600 9px/1 ui-monospace,monospace;letter-spacing:.16em;color:#9aa6b0;padding:4px 0;border-bottom:1px solid transparent}
.foot-links button:hover{color:#fff;border-bottom-color:var(--red-hi)}
.foot-ver{font:500 9px/1 ui-monospace,monospace;letter-spacing:.1em;color:#59646d}

/* ---------- HUD ---------- */
#hud{pointer-events:none;z-index:15}
#hud button{pointer-events:auto}
.hud-top-left{position:absolute;top:calc(14px + var(--safe-t));left:calc(16px + var(--safe-l));display:flex;gap:10px;align-items:flex-start}
.icon-btn{width:38px;height:38px;border:1px solid var(--line);background:rgba(8,11,14,.66);backdrop-filter:blur(8px);
  color:#d8e1e8;font-size:11px;letter-spacing:.05em;border-radius:2px;display:grid;place-items:center}
.icon-btn:hover{border-color:rgba(255,255,255,.3);background:rgba(20,26,32,.8)}
.mission-panel{min-width:270px;max-width:360px;padding:10px 13px 11px;background:linear-gradient(100deg,rgba(8,11,14,.82),rgba(8,11,14,.55));
  border:1px solid var(--line);border-left:2px solid var(--red);backdrop-filter:blur(9px)}
.mission-kicker{font:700 8px/1 ui-monospace,monospace;letter-spacing:.22em;color:var(--red-hi)}
.mission-title{font:800 14px/1.15 "Arial Narrow",Arial,sans-serif;letter-spacing:.06em;margin-top:6px}
.mission-obj{display:flex;gap:7px;align-items:center;margin-top:8px;font-size:10.5px;color:#c0cbd4}
.mission-obj i{width:5px;height:5px;background:var(--gold);transform:rotate(45deg);flex:none}
.mission-track{height:2px;background:rgba(255,255,255,.12);margin-top:9px;overflow:hidden}
#mission-progress{height:100%;width:0;background:linear-gradient(90deg,var(--red),var(--gold));transition:width .25s}

.hud-top-right{position:absolute;top:calc(14px + var(--safe-t));right:calc(16px + var(--safe-r));display:flex;flex-direction:column;align-items:flex-end;gap:7px}
.minimap-wrap{position:relative;width:166px;height:166px;border:1px solid rgba(255,255,255,.18);border-radius:50%;
  background:rgba(6,9,12,.68);backdrop-filter:blur(8px);overflow:hidden;box-shadow:0 8px 30px rgba(0,0,0,.35)}
#minimap{width:100%;height:100%;display:block}
.map-compass{position:absolute;top:5px;left:50%;transform:translateX(-50%);font:700 8px/1 ui-monospace,monospace;color:var(--red-hi);letter-spacing:.1em}
.map-zone{position:absolute;bottom:9px;left:50%;transform:translateX(-50%);font:700 7px/1 ui-monospace,monospace;
  letter-spacing:.18em;color:#aebac4;background:rgba(0,0,0,.4);padding:4px 6px;border-radius:2px;white-space:nowrap}
.threat-row{display:flex;align-items:center;gap:5px;font:600 9px/1 ui-monospace,monospace;letter-spacing:.1em;color:#a7b3bd;
  background:rgba(6,9,12,.6);border:1px solid var(--line-soft);padding:6px 9px;border-radius:2px;backdrop-filter:blur(6px)}
.threat-row b{color:#fff;font-size:11px}
.threat-row .sep{color:#4e5a64}
.pulse-dot{width:5px;height:5px;border-radius:50%;background:var(--red-hi);box-shadow:0 0 8px var(--red-hi);animation:pulse 1.4s infinite}
@keyframes pulse{50%{opacity:.25;transform:scale(.7)}}

.boss-bar{position:absolute;top:calc(86px + var(--safe-t));left:50%;transform:translateX(-50%);width:min(440px,52vw);text-align:center}
.boss-name{font:800 11px/1 "Arial Narrow",Arial,sans-serif;letter-spacing:.3em;color:#ffb4a7;text-shadow:0 0 20px rgba(200,55,45,.6)}
.boss-track{height:5px;background:rgba(255,255,255,.13);margin-top:7px;border:1px solid rgba(0,0,0,.4)}
#boss-fill{height:100%;width:100%;background:linear-gradient(90deg,#7e1a14,#e04432,#ff8b68);transition:width .2s}
.boss-sub{font:500 8px/1 ui-monospace,monospace;letter-spacing:.12em;color:#8e9aa4;margin-top:6px}

.vitals{position:absolute;left:calc(18px + var(--safe-l));bottom:calc(24px + var(--safe-b));width:240px;display:flex;flex-direction:column;gap:7px}
.vital{display:grid;grid-template-columns:40px 1fr 30px;align-items:center;gap:7px;font:700 8px/1 ui-monospace,monospace;letter-spacing:.12em;color:#9daab4}
.vital .track{height:5px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.12);overflow:hidden}
.vital b{text-align:right;color:#dbe4ea;font-size:9px;letter-spacing:0}
.vital.hp .track>div{height:100%;width:100%;background:linear-gradient(90deg,#a9231b,#e04432);transition:width .15s}
.vital.gas .track>div{height:100%;width:100%;background:linear-gradient(90deg,#247f92,#5fc9dd);transition:width .1s}
.vital.blade .track>div{height:100%;width:100%;background:linear-gradient(90deg,#9c8a55,#e3bf78);transition:width .1s}
.vital.hp.low .track>div{animation:lowhp .6s infinite alternate}
@keyframes lowhp{to{filter:brightness(1.8)}}

.combo-wrap{position:absolute;right:calc(26px + var(--safe-r));top:42%;text-align:right;transform:translateY(-50%)}
.combo-num{font:900 46px/.8 "Arial Black",sans-serif;letter-spacing:-.03em;color:#fff;text-shadow:0 0 26px rgba(255,91,65,.45)}
.combo-label{font:700 8px/1 ui-monospace,monospace;letter-spacing:.24em;color:var(--gold);margin-top:5px}
.combo-label span{color:#fff}
.combo-track{height:2px;width:90px;margin:6px 0 0 auto;background:rgba(255,255,255,.13)}
#combo-fill{height:100%;width:100%;background:var(--gold)}

.lock-reticle{position:absolute;left:50%;top:50%;width:92px;height:92px;transform:translate(-50%,-50%);pointer-events:none}
.reticle-ring{position:absolute;inset:0;border:1px solid rgba(255,255,255,.28);border-radius:50%;
  clip-path:polygon(0 0,32% 0,32% 3%,3% 3%,3% 32%,0 32%,0 68%,3% 68%,3% 97%,32% 97%,32% 100%,68% 100%,68% 97%,97% 97%,97% 68%,100% 68%,100% 32%,97% 32%,97% 3%,68% 3%,68% 0);
  animation:reticlePulse 1.6s infinite}
.reticle-diamond{position:absolute;left:50%;top:50%;width:14px;height:14px;border:1px solid var(--red-hi);transform:translate(-50%,-50%) rotate(45deg);box-shadow:0 0 10px rgba(255,91,65,.5)}
@keyframes reticlePulse{50%{opacity:.5;transform:scale(.94)}}
.lock-label{position:absolute;left:50%;top:-17px;transform:translateX(-50%);font:700 7px/1 ui-monospace,monospace;letter-spacing:.14em;color:#ffd9d1;white-space:nowrap}
.lock-hp{position:absolute;left:50%;bottom:-9px;transform:translateX(-50%);width:64px;height:3px;background:rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.2)}
#lock-hp-fill{height:100%;width:100%;background:var(--red-hi)}
.lock-dist{position:absolute;right:-30px;top:50%;transform:translateY(-50%);font:600 8px/1 ui-monospace,monospace;color:#c4ced6}

.crosshair{position:absolute;left:50%;top:50%;width:20px;height:20px;transform:translate(-50%,-50%);opacity:.55}
.crosshair i{position:absolute;background:rgba(255,255,255,.8)}
.crosshair i:nth-child(1){left:9px;top:0;width:1px;height:6px}
.crosshair i:nth-child(2){left:9px;bottom:0;width:1px;height:6px}
.crosshair i:nth-child(3){top:9px;left:0;height:1px;width:6px}
.crosshair i:nth-child(4){top:9px;right:0;height:1px;width:6px}
.crosshair span{position:absolute;left:9px;top:9px;width:2px;height:2px;border-radius:50%;background:var(--red-hi)}
.lock-reticle:not(.hidden)~.crosshair{opacity:0}

.squad-panel{position:absolute;left:calc(18px + var(--safe-l));top:calc(140px + var(--safe-t));width:170px;
  background:rgba(8,11,14,.55);border:1px solid var(--line-soft);padding:8px 9px;backdrop-filter:blur(6px)}
.squad-title{font:700 7px/1 ui-monospace,monospace;letter-spacing:.24em;color:#8c99a3;margin-bottom:7px}
.squad-row{display:grid;grid-template-columns:16px 1fr 24px;align-items:center;gap:5px;margin:5px 0;font:600 8px/1 ui-monospace,monospace;color:#c3cdd5}
.squad-row .dot{width:6px;height:6px;border-radius:50%;background:var(--green);margin-left:3px}
.squad-row.down .dot{background:#e04432}
.squad-row.down{color:#ff9d8f}
.squad-row .bar{height:2px;background:rgba(255,255,255,.12);margin-top:3px}
.squad-row .bar div{height:100%;background:var(--green)}
.squad-row.down .bar div{background:#e04432}
.squad-row small{font-size:7px;color:#8995a0;text-align:right}

.zone-banner{position:absolute;left:50%;top:22%;transform:translateX(-50%);text-align:center;animation:zoneIn 3.2s forwards}
.zone-banner span{display:block;font:900 clamp(20px,3vw,32px)/1 "Arial Black",sans-serif;letter-spacing:.2em;color:#fff;text-shadow:0 4px 30px #000}
.zone-banner small{display:block;margin-top:7px;font:600 9px/1 ui-monospace,monospace;letter-spacing:.22em;color:#c9d3db}
@keyframes zoneIn{0%{opacity:0;transform:translate(-50%,8px)}12%{opacity:1;transform:translate(-50%,0)}80%{opacity:1}100%{opacity:0}}

.objective-beacon{position:absolute;left:50%;bottom:24%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;
  background:rgba(8,11,14,.62);border:1px solid rgba(227,191,120,.3);padding:6px 11px;font:700 8px/1 ui-monospace,monospace;letter-spacing:.12em;color:#dfe7ed}
.objective-beacon i{width:6px;height:6px;background:var(--gold);transform:rotate(45deg);box-shadow:0 0 10px var(--gold)}
.objective-beacon b{color:var(--gold)}

.interact-prompt{position:absolute;left:50%;bottom:31%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;
  background:rgba(8,11,14,.78);border:1px solid var(--line);padding:9px 13px;font:700 10px/1 ui-monospace,monospace;letter-spacing:.1em}
.interact-prompt kbd{background:var(--red);border-color:var(--red-hi);color:#fff}

.toasts{position:absolute;right:calc(20px + var(--safe-r));top:calc(230px + var(--safe-t));display:flex;flex-direction:column;gap:6px;align-items:flex-end;width:280px}
.toast{font:600 9px/1.4 ui-monospace,monospace;letter-spacing:.06em;color:#e7eef4;background:rgba(8,11,14,.8);
  border-right:2px solid var(--red-hi);padding:7px 10px;animation:toastIn .22s ease;max-width:100%;text-align:right}
.toast.gold{border-right-color:var(--gold);color:var(--gold)}
.toast.green{border-right-color:var(--green)}
.toast.out{animation:toastOut .3s forwards}
@keyframes toastIn{from{opacity:0;transform:translateX(14px)}}
@keyframes toastOut{to{opacity:0;transform:translateX(14px)}}

.damage-layer{position:absolute;inset:0;overflow:hidden;pointer-events:none}
.dmg-num{position:absolute;font:900 16px/1 "Arial Black",sans-serif;color:#fff;text-shadow:0 2px 6px #000;transform:translate(-50%,-50%);
  animation:dmgUp .8s ease-out forwards;letter-spacing:-.02em}
.dmg-num.crit{color:#ffd26e;font-size:24px}
.dmg-num.heal{color:var(--green)}
@keyframes dmgUp{0%{opacity:0;transform:translate(-50%,-30%) scale(.7)}15%{opacity:1;transform:translate(-50%,-50%) scale(1.08)}100%{opacity:0;transform:translate(-50%,-180%) scale(.95)}}

.dialogue{position:absolute;left:50%;bottom:calc(26px + var(--safe-b));transform:translateX(-50%);width:min(720px,80vw);
  display:flex;gap:14px;align-items:center;background:linear-gradient(100deg,rgba(8,11,14,.94),rgba(12,17,22,.88));
  border:1px solid var(--line);border-left:2px solid var(--red);padding:12px 14px;backdrop-filter:blur(10px);pointer-events:auto}
.dlg-portrait{width:42px;height:42px;flex:none;display:grid;place-items:center;border:1px solid rgba(255,255,255,.2);
  background:linear-gradient(145deg,#2f3942,#141a1f);font:900 16px/1 "Arial Black";color:var(--gold)}
.dlg-body{flex:1;min-width:0}
.dlg-body b{font:700 8px/1 ui-monospace,monospace;letter-spacing:.2em;color:var(--red-hi)}
.dlg-body p{margin:5px 0 0;font-size:12.5px;line-height:1.5;color:#d7e0e7}
#dlg-next{font:700 8px/1 ui-monospace,monospace;letter-spacing:.14em;color:#fff;border:1px solid var(--line);padding:9px 11px;white-space:nowrap}

.joystick{display:none;position:absolute;left:calc(20px + var(--safe-l));bottom:calc(22px + var(--safe-b));width:132px;height:150px;
  pointer-events:auto;touch-action:none}
.joy-ring{position:absolute;left:0;bottom:18px;width:128px;height:128px;border-radius:50%;border:1px solid rgba(255,255,255,.2);
  background:radial-gradient(circle,rgba(255,255,255,.06),rgba(0,0,0,.34) 68%);backdrop-filter:blur(3px);
  box-shadow:inset 0 0 24px rgba(0,0,0,.4)}
.joy-ring::before,.joy-ring::after{content:"";position:absolute;background:rgba(255,255,255,.1)}
.joy-ring::before{left:50%;top:9%;bottom:9%;width:1px}
.joy-ring::after{top:50%;left:9%;right:9%;height:1px}
.joy-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;margin:-27px 0 0 -27px;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.28),rgba(20,27,33,.9) 62%);
  border:1px solid rgba(255,255,255,.35);box-shadow:0 4px 16px rgba(0,0,0,.5),inset 0 0 12px rgba(255,255,255,.06);transition:transform .06s}
.joy-label{position:absolute;bottom:0;left:50%;transform:translateX(-50%);font:700 7px/1 ui-monospace,monospace;letter-spacing:.2em;color:#8e9ba5}

.touch-actions{display:none;position:absolute;right:calc(16px + var(--safe-r));bottom:calc(18px + var(--safe-b));
  width:230px;height:220px;pointer-events:none}
.act-btn{position:absolute;pointer-events:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;
  border-radius:50%;border:1px solid rgba(255,255,255,.24);background:radial-gradient(circle at 35% 28%,rgba(255,255,255,.16),rgba(12,17,22,.72) 66%);
  box-shadow:0 5px 18px rgba(0,0,0,.35),inset 0 0 0 1px rgba(0,0,0,.2);backdrop-filter:blur(4px);transition:transform .08s,background .08s;
  touch-action:none;user-select:none}
.act-btn:active,.act-btn.pressed{transform:scale(.9);background:radial-gradient(circle at 35% 28%,rgba(255,255,255,.3),rgba(200,55,45,.45) 70%)}
.act-btn span{font:400 20px/1 Arial,sans-serif}
.act-btn em{font:700 6.5px/1 ui-monospace,monospace;letter-spacing:.12em;font-style:normal;color:#c6d0d8}
.act-btn.attack{right:0;bottom:0;width:92px;height:92px;border-color:rgba(255,110,85,.55);background:radial-gradient(circle at 35% 28%,rgba(255,140,110,.34),rgba(120,24,18,.65) 68%)}
.act-btn.attack span{font-size:32px}
.act-btn.attack em{font-size:8px;color:#ffd5cc}
.act-btn.medium{width:66px;height:66px}
.act-btn.medium.hook{right:88px;bottom:52px;border-color:rgba(111,214,232,.45)}
.act-btn.medium.boost{right:18px;bottom:98px;border-color:rgba(227,191,120,.45)}
.act-btn.medium[data-action="jump"]{right:104px;bottom:4px}
.act-btn.small{width:50px;height:50px}
.act-btn.small[data-action="dodge"]{right:164px;bottom:88px}
.act-btn.small[data-action="lock"]{right:80px;bottom:132px;border-color:rgba(200,55,45,.45)}
.act-btn.small span{font-size:16px}
.act-btn.small em{font-size:5.5px}

.desktop-hints{position:absolute;left:50%;bottom:calc(12px + var(--safe-b));transform:translateX(-50%);display:flex;gap:13px;flex-wrap:wrap;justify-content:center;
  font:500 8px/1 ui-monospace,monospace;letter-spacing:.08em;color:#7c8993;background:rgba(6,9,12,.48);padding:7px 12px;border:1px solid var(--line-soft);border-radius:2px;backdrop-filter:blur(6px)}
.desktop-hints kbd{font-size:8px;padding:2px 3px}

body.touch .joystick,body.touch .touch-actions{display:block}
body.touch .desktop-hints{display:none}
body.touch .vitals{bottom:calc(182px + var(--safe-b));width:200px}
body.touch .mission-panel{min-width:0;max-width:240px}
body.touch .mission-title{font-size:12px}
body.touch .minimap-wrap{width:112px;height:112px}
body.touch .hud-top-right{gap:5px}
body.touch .threat-row{font-size:8px;padding:4px 6px}
body.touch .squad-panel{top:calc(130px + var(--safe-t));width:148px}
body.touch .toasts{top:calc(180px + var(--safe-t));width:210px}
body.touch .combo-wrap{right:calc(16px + var(--safe-r));top:34%}
body.touch .combo-num{font-size:34px}
body.touch .boss-bar{top:calc(76px + var(--safe-t));width:56vw}
body.touch .dialogue{bottom:calc(150px + var(--safe-b));width:min(520px,90vw)}
body.touch .objective-beacon{bottom:34%}
body.touch .interact-prompt{bottom:40%}

/* ---------- OVERLAY ---------- */
#overlay{background:rgba(4,6,8,.72);backdrop-filter:blur(8px);display:grid;place-items:center;padding:calc(20px + var(--safe-t)) calc(18px + var(--safe-r)) calc(20px + var(--safe-b)) calc(18px + var(--safe-l));z-index:40}
.overlay-card{width:min(920px,100%);max-height:100%;overflow:auto;background:linear-gradient(155deg,rgba(17,22,27,.98),rgba(8,11,14,.98));
  border:1px solid var(--line);box-shadow:0 30px 90px rgba(0,0,0,.6);position:relative}
.overlay-card::before{content:"";position:absolute;left:0;top:0;right:0;height:2px;background:linear-gradient(90deg,var(--red),transparent 60%)}
.ov-head{display:flex;align-items:flex-start;gap:16px;padding:24px 26px 18px;border-bottom:1px solid var(--line-soft)}
.ov-kicker{font:700 8px/1 ui-monospace,monospace;letter-spacing:.26em;color:var(--red-hi)}
.ov-head h2{margin:7px 0 0;font:900 clamp(22px,3vw,34px)/1 "Arial Black",sans-serif;letter-spacing:.02em}
.ov-head p{margin:7px 0 0;font-size:11px;line-height:1.5;color:var(--muted);max-width:560px}
.ov-close{margin-left:auto;width:34px;height:34px;border:1px solid var(--line);font-size:15px;color:#b7c2cb;flex:none}
.ov-close:hover{border-color:var(--red-hi);color:#fff}
.ov-body{padding:20px 26px 26px}
.ov-foot{display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap;padding:16px 26px;border-top:1px solid var(--line-soft);background:rgba(0,0,0,.18)}

.settings-group{margin-bottom:22px}
.settings-group h3{font:700 9px/1 ui-monospace,monospace;letter-spacing:.22em;color:#8c99a3;margin:0 0 12px;padding-bottom:8px;border-bottom:1px solid var(--line-soft)}
.setting-row{display:flex;align-items:center;gap:16px;padding:9px 0;min-height:42px}
.setting-row>label,.setting-row .lbl{flex:1;font-size:12px;color:#d3dde5}
.setting-row small{display:block;color:#7d8994;font-size:9.5px;margin-top:3px;line-height:1.35}
.seg{display:flex;border:1px solid var(--line);background:rgba(0,0,0,.25);flex-wrap:wrap}
.seg button{padding:7px 10px;font:600 9px/1 ui-monospace,monospace;letter-spacing:.06em;color:#8d99a3;border-right:1px solid var(--line-soft)}
.seg button:last-child{border-right:0}
.seg button.active{background:rgba(200,55,45,.28);color:#fff;box-shadow:inset 0 -2px 0 var(--red-hi)}
.toggle{width:46px;height:24px;border:1px solid var(--line);border-radius:999px;background:rgba(0,0,0,.3);position:relative;flex:none}
.toggle::after{content:"";position:absolute;width:16px;height:16px;border-radius:50%;background:#5d6973;left:3px;top:3px;transition:.18s}
.toggle.on{background:rgba(99,214,155,.2);border-color:rgba(99,214,155,.5)}
.toggle.on::after{background:var(--green);transform:translateX(22px)}
input[type=range]{-webkit-appearance:none;width:170px;height:3px;background:rgba(255,255,255,.16);outline:none}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:var(--red-hi);border:2px solid #fff2;box-shadow:0 0 10px rgba(255,91,65,.5)}
.setting-val{font:600 10px/1 ui-monospace,monospace;color:var(--gold);width:44px;text-align:right}

.upgrade-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.up-card{border:1px solid var(--line);background:rgba(255,255,255,.025);padding:14px;position:relative;overflow:hidden}
.up-card::after{content:"";position:absolute;right:-20px;top:-20px;width:70px;height:70px;border:1px solid rgba(255,255,255,.05);border-radius:50%}
.up-top{display:flex;align-items:center;gap:10px}
.up-icon{width:38px;height:38px;display:grid;place-items:center;font-size:17px;background:rgba(255,255,255,.05);border:1px solid var(--line-soft)}
.up-name{font:800 12px/1 "Arial Narrow",Arial,sans-serif;letter-spacing:.08em}
.up-lvl{font:600 8px/1 ui-monospace,monospace;color:var(--gold);margin-top:5px;letter-spacing:.1em}
.up-desc{font-size:10px;color:#94a0aa;line-height:1.45;margin:10px 0}
.up-pips{display:flex;gap:3px;margin:8px 0 11px}
.up-pips i{height:3px;flex:1;background:rgba(255,255,255,.12)}
.up-pips i.on{background:var(--gold);box-shadow:0 0 6px rgba(227,191,120,.4)}
.up-buy{display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;border:1px solid rgba(227,191,120,.3);
  background:rgba(227,191,120,.07);padding:8px 10px;font:700 9px/1 ui-monospace,monospace;color:var(--gold);letter-spacing:.05em}
.up-buy:hover{background:rgba(227,191,120,.14)}
.up-buy:disabled{opacity:.4;color:#84909a;border-color:var(--line);background:rgba(255,255,255,.02)}
.up-stats{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:18px;padding:11px 14px;border:1px solid var(--line-soft);background:rgba(0,0,0,.2)}
.up-stats div{font:600 9px/1.4 ui-monospace,monospace;color:#95a1ab}
.up-stats b{display:block;color:#fff;font-size:12px;margin-top:2px}

.story-list{display:flex;flex-direction:column;gap:8px}
.chapter{display:grid;grid-template-columns:46px 1fr auto;gap:14px;align-items:center;border:1px solid var(--line);padding:12px 14px;background:rgba(255,255,255,.02);text-align:left;transition:.15s}
.chapter:hover:not(.locked){border-color:rgba(255,255,255,.28);background:rgba(255,255,255,.045)}
.chapter.locked{opacity:.42}
.chapter .num{font:900 22px/1 "Arial Black",sans-serif;color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.45)}
.chapter.done .num{color:var(--gold);-webkit-text-stroke:0}
.chapter b{display:block;font:800 12px/1.2 "Arial Narrow",Arial,sans-serif;letter-spacing:.06em}
.chapter span{display:block;font-size:9.5px;color:var(--muted);margin-top:4px;line-height:1.4}
.chapter .go{font:700 8px/1 ui-monospace,monospace;letter-spacing:.14em;color:var(--red-hi)}
.chapter .go.locked{color:#6f7b85}

.controls-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.ctrl-row{display:flex;align-items:center;gap:10px;border:1px solid var(--line-soft);padding:10px 12px;background:rgba(255,255,255,.02)}
.ctrl-keys{display:flex;gap:3px;min-width:92px}
.ctrl-row span{font-size:10.5px;color:#b7c3cc}
.ctrl-row em{font-style:normal;color:#7d8993;font-size:9px;margin-left:auto;text-align:right}

.result-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:4px 0 20px}
.result-stat{border:1px solid var(--line);background:rgba(255,255,255,.025);padding:13px 10px;text-align:center}
.result-stat b{display:block;font:900 24px/1 "Arial Narrow",Arial,sans-serif;color:#fff}
.result-stat span{display:block;margin-top:5px;font:600 7.5px/1.2 ui-monospace,monospace;letter-spacing:.14em;color:#8c98a2}
.reward-line{display:flex;align-items:center;justify-content:space-between;border:1px solid rgba(227,191,120,.25);background:rgba(227,191,120,.06);padding:12px 15px;margin-bottom:18px}
.reward-line span{font:600 10px/1 ui-monospace,monospace;letter-spacing:.08em;color:#c4b084}
.reward-line b{font:900 22px/1 "Arial Black",sans-serif;color:var(--gold)}
.result-title.win{color:#c9f5de}
.result-title.lose{color:#ffb3a7}

.pause-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.pause-grid .btn{width:100%;height:46px}
.dialog-script{max-height:46vh;overflow:auto;padding-right:6px}
.dialog-script p{font-size:12px;line-height:1.65;color:#b8c4cd;margin:0 0 12px}
.dialog-script p b{color:var(--red-hi);font:700 9px/1 ui-monospace,monospace;letter-spacing:.1em;margin-right:8px}
.objective-list{display:flex;flex-direction:column;gap:6px;margin:12px 0 18px}
.objective-list div{display:flex;gap:8px;align-items:flex-start;font-size:11px;color:#b9c5ce;line-height:1.45}
.objective-list i{width:5px;height:5px;margin-top:5px;background:var(--gold);transform:rotate(45deg);flex:none}
.brief-art{height:120px;border:1px solid var(--line);margin-bottom:16px;position:relative;overflow:hidden;
  background:radial-gradient(circle at 70% 40%,rgba(200,55,45,.25),transparent 50%),linear-gradient(120deg,#10161b,#080b0e)}
.brief-art::before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(115deg,transparent 0 24px,rgba(255,255,255,.025) 24px 25px)}
.brief-art b{position:absolute;left:18px;bottom:16px;font:900 clamp(20px,3vw,32px)/1 "Arial Black",sans-serif;letter-spacing:.05em;color:#fff}
.brief-art span{position:absolute;left:20px;bottom:8px;font:600 7px/1 ui-monospace,monospace;letter-spacing:.22em;color:var(--red-hi)}

#rotate-hint{position:fixed;left:50%;top:12px;transform:translateX(-50%);z-index:100;background:rgba(0,0,0,.8);
  border:1px solid var(--line);padding:8px 12px;font:600 9px/1 ui-monospace,monospace;letter-spacing:.08em;color:#c8d2da;border-radius:4px}

/* ---------- RESPONSIVE ---------- */
@media (max-width:1080px){
  .menu-main{grid-template-columns:1fr 1fr;gap:30px}
  .hero-copy>p{font-size:12px}
  h1{font-size:clamp(48px,7vw,80px)}
  .mode-card{grid-template-columns:38px 1fr 16px;min-height:72px;padding:11px 12px;gap:10px}
  .mode-icon{width:38px;height:38px;font-size:16px}
  .mode-copy b{font-size:10.5px}
  .mode-copy span{font-size:8.5px}
}
@media (max-width:820px){
  #menu{overflow:auto}
  .menu-head{padding:calc(12px + var(--safe-t)) calc(16px + var(--safe-r)) 0 calc(16px + var(--safe-l));gap:8px}
  .brand-mark{width:26px;height:26px}
  .brand strong{font-size:12px}
  .brand span{font-size:6px}
  .profile-chip{padding:4px 9px 4px 4px}
  .profile-chip .avatar{width:24px;height:24px;font-size:10px}
  .profile-chip b{font-size:9px}.profile-chip span{font-size:7px}
  .coin-chip{padding:7px 9px;font-size:10px}
  .menu-main{display:flex;flex-direction:column;height:auto;padding:26px calc(16px + var(--safe-r)) 90px calc(16px + var(--safe-l));gap:24px}
  .hero-copy{max-width:none;padding:0}
  .eyebrow{font-size:8px}
  h1{font-size:clamp(48px,14vw,74px);margin:12px 0 12px}
  h1 span{font-size:.5em}
  .hero-copy>p{font-size:11.5px;max-width:360px;margin-bottom:16px}
  .hero-stats{padding:11px 0;gap:22px}
  .hero-stats b{font-size:19px}.hero-stats span{font-size:7px}
  .hero-actions{margin-top:16px}
  .btn{height:42px;font-size:9px;padding:0 16px}
  .mode-grid{gap:8px}
  .mode-card{min-height:76px;grid-template-columns:34px 1fr;gap:9px;padding:10px}
  .mode-go{display:none}
  .mode-icon{width:34px;height:34px;font-size:14px}
  .mode-copy b{font-size:9.5px}
  .mode-copy span{font-size:8px}
  .menu-foot{position:relative;left:auto;right:auto;bottom:auto;margin:0 16px 20px;flex-wrap:wrap;gap:10px}
  .foot-hint{display:none}
  .foot-links{margin-left:0;gap:14px}
  .foot-ver{margin-left:auto}
}
@media (max-width:520px){
  .mode-grid{grid-template-columns:1fr}
  .mode-card{min-height:62px}
  .hero-stats{gap:16px}
  .hero-stats b{font-size:17px}
  .profile-chip{display:none}
  .overlay-card{max-height:100%}
  .ov-head{padding:18px 16px 14px}
  .ov-body{padding:14px 16px 18px}
