export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
export const rand = (a = 0, b = 1) => a + Math.random() * (b - a);
export const randInt = (a, b) => Math.floor(rand(a, b + 1));
export const pick = arr => arr[Math.floor(Math.random() * arr.length)];
export const dist2D = (a, b) => Math.hypot(a.x - b.x, a.z - b.z);
export const fmt = n => Math.round(n).toLocaleString('vi-VN');
export function angleDelta(a, b) {
  let d = (b - a + Math.PI) % (Math.PI * 2) - Math.PI;
  if (d < -Math.PI) d += Math.PI * 2;
  return d;
}

import { UPGRADES, RANKS } from './config.js';

const KEY = 'titan-slayer-save-v1';

function defaults() {
  const upgrades = {};
  for (const k of Object.keys(UPGRADES)) upgrades[k] = 0;
  return {
    version: 1,
    coins: 120,
    xp: 0,
    kills: 0,
    deaths: 0,
    missions: 0,
    bestSurvival: 0,
    bestSquad: 0,
    storyProgress: 0,
    storyDone: [],
    tutorialDone: false,
    upgrades,
    settings: {
      quality: 'high',
      fps: 60,
      sensitivity: 1,
      sound: true,
      music: true,
      vibration: true,
      invertY: false,
      showFps: true,
      shake: true,
      autoLock: true
    },
    seenIntro: false
  };
}

export const Save = {
  data: defaults(),
  load() {
    try {
      const raw = localStorage.getItem(KEY);
      if (!raw) return this.data;
      const parsed = JSON.parse(raw);
      const base = defaults();
      this.data = {
        ...base, ...parsed,
        upgrades: { ...base.upgrades, ...(parsed.upgrades || {}) },
        settings: { ...base.settings, ...(parsed.settings || {}) },
        storyDone: Array.isArray(parsed.storyDone) ? parsed.storyDone : []
      };
      this.data.coins = Number(this.data.coins) || 0;
      this.data.xp = Number(this.data.xp) || 0;
    } catch (e) {
      console.warn('Save load failed', e);
      this.data = defaults();
    }
    return this.data;
  },
  save() {
    try { localStorage.setItem(KEY, JSON.stringify(this.data)); } catch (e) { /* private mode */ }
  },
  reset() {
    this.data = defaults();
    this.save();
  },
  get settings() { return this.data.settings; },
  get upgrades() { return this.data.upgrades; },
  upgradeCost(key) {
    const u = UPGRADES[key];
    const lvl = this.data.upgrades[key] || 0;
    return Math.round(u.baseCost * Math.pow(u.growth, lvl));
  },
  buy(key) {
    const u = UPGRADES[key];
    const lvl = this.data.upgrades[key] || 0;
    if (lvl >= u.max) return { ok: false, reason: 'max' };
    const cost = this.upgradeCost(key);
    if (this.data.coins < cost) return { ok: false, reason: 'coins' };
    this.data.coins -= cost;
    this.data.upgrades[key] = lvl + 1;
    this.save();
    return { ok: true, cost, level: lvl + 1 };
  },
  stats() {
    const u = this.data.upgrades;
    const s = {
      damage: 1, gas: 100, reel: 1, hookRange: 120, hp: 100, regen: 1.2,
      armor: 1, comboWindow: 1.25, finisher: 1
    };
    for (const key of Object.keys(UPGRADES)) {
      const applied = UPGRADES[key].apply(u[key] || 0);
      Object.assign(s, applied);
    }
    return s;
  },
  addXp(n) {
    this.data.xp += Math.max(0, Math.round(n));
    this.save();
  },
  addCoins(n) {
    this.data.coins += Math.max(0, Math.round(n));
    this.save();
  },
  rank() {
    let out = RANKS[0];
    for (const r of RANKS) if (this.data.xp >= r.xp) out = r;
    return out;
  },
  rankProgress() {
    let idx = 0;
    for (let i = 0; i < RANKS.length; i++) if (this.data.xp >= RANKS[i].xp) idx = i;
    const cur = RANKS[idx], next = RANKS[idx + 1];
    if (!next) return { pct: 1, cur, next: null };
    return { pct: (this.data.xp - cur.xp) / (next.xp - cur.xp), cur, next };
  },
  completeStory(index, reward) {
    if (!this.data.storyDone.includes(index)) this.data.storyDone.push(index);
    this.data.storyProgress = Math.max(this.data.storyProgress, Math.min(5, index + 1));
    this.data.coins += reward;
    this.data.missions += 1;
    this.save();
  },
  settingsChanged() { this.save(); }
};

// Procedural WebAudio — no external assets, works offline.
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.musicOn = true;
    this.ambientStarted = false;
    this.last = {};
  }
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = 0.5;
    this.master.connect(this.ctx.destination);
    this.noiseBuf = this.makeNoise(2.2);
    this.startAmbient();
  }
  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const w = Math.random() * 2 - 1;
      last = last * 0.94 + w * 0.06;
      d[i] = last * 2.4;
    }
    return buf;
  }
  setMuted(m) { this.muted = m; if (this.master) this.master.gain.value = m ? 0 : 0.5; }
  setMusic(on) {
    this.musicOn = on;
    if (this.musicGain) this.musicGain.gain.value = on ? 0.035 : 0;
  }
  startAmbient() {
    if (!this.ctx || this.ambientStarted) return;
    this.ambientStarted = true;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuf; src.loop = true;
    const lp = this.ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 420; lp.Q.value = 0.6;
    const g = this.ctx.createGain(); g.gain.value = 0.055;
    src.connect(lp).connect(g).connect(this.master);
    src.start();
    const lfo = this.ctx.createOscillator(); lfo.frequency.value = 0.07;
    const lfoG = this.ctx.createGain(); lfoG.gain.value = 0.022;
    lfo.connect(lfoG).connect(g.gain); lfo.start();

    // low cinematic drone
    const mg = this.ctx.createGain(); mg.gain.value = this.musicOn ? 0.035 : 0;
    this.musicGain = mg;
    const lp2 = this.ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = 180;
    const o1 = this.ctx.createOscillator(); o1.type = 'sawtooth'; o1.frequency.value = 55;
    const o2 = this.ctx.createOscillator(); o2.type = 'sawtooth'; o2.frequency.value = 55.6;
    const o3 = this.ctx.createOscillator(); o3.type = 'sine'; o3.frequency.value = 110;
    const g3 = this.ctx.createGain(); g3.gain.value = 0.28;
    o1.connect(lp2); o2.connect(lp2); o3.connect(g3).connect(lp2);
    lp2.connect(mg).connect(this.master);
    o1.start(); o2.start(); o3.start();
    const mlfo = this.ctx.createOscillator(); mlfo.frequency.value = 0.045;
    const mlg = this.ctx.createGain(); mlg.gain.value = 40;
    mlfo.connect(mlg).connect(lp2.frequency); mlfo.start();
  }
  env(gain, a, d, peak = 1) {
    const t = this.ctx.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), t + a);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + a + d);
  }
  noise(dur = 0.2, filter = 'bandpass', freq = 900, q = 0.8, vol = 0.3) {
    if (!this.ctx || this.muted) return;
    const src = this.ctx.createBufferSource(); src.buffer = this.noiseBuf;
    src.loop = true;
    const f = this.ctx.createBiquadFilter(); f.type = filter; f.frequency.value = freq; f.Q.value = q;
    const g = this.ctx.createGain(); g.gain.value = 0;
    src.connect(f).connect(g).connect(this.master);
    const t = this.ctx.currentTime;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    src.start(); src.stop(t + dur + 0.05);
  }
  tone(freq, dur = 0.2, type = 'sine', vol = 0.2, slide = 1) {
    if (!this.ctx || this.muted) return;
    const o = this.ctx.createOscillator(); o.type = type;
    const g = this.ctx.createGain();
    const t = this.ctx.currentTime;
    o.frequency.setValueAtTime(freq, t);
    o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.015);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g).connect(this.master); o.start(); o.stop(t + dur + 0.03);
  }
  play(name, opt = {}) {
    if (!this.ctx || this.muted) return;
    const now = performance.now();
    const gate = { swing: 55, hit: 45, step: 220, ui: 40, slash: 60 }[name] || 30;
    if (this.last[name] && now - this.last[name] < gate) return;
    this.last[name] = now;
    switch (name) {
      case 'ui': this.tone(420, 0.06, 'triangle', 0.08, 1.4); break;
      case 'confirm': this.tone(330, 0.1, 'triangle', 0.1, 1.5); setTimeout(() => this.tone(660, 0.12, 'triangle', 0.07, 1.2), 55); break;
      case 'swing': this.noise(0.16, 'bandpass', 1400, 1.4, 0.22); break;
      case 'slash': this.noise(0.13, 'highpass', 1800, 1, 0.26); this.tone(240, 0.09, 'sawtooth', 0.08, 0.5); break;
      case 'hit': this.noise(0.09, 'lowpass', 700, 0.8, 0.34); this.tone(95, 0.12, 'square', 0.15, 0.6); break;
      case 'crit': this.noise(0.18, 'bandpass', 2100, 1, 0.4); this.tone(150, 0.25, 'sawtooth', 0.24, 0.35); break;
      case 'grapple': this.tone(720, 0.12, 'square', 0.1, 2.4); this.noise(0.1, 'highpass', 2600, 1, 0.14); break;
      case 'release': this.tone(540, 0.08, 'triangle', 0.07, 0.5); break;
      case 'jump': this.noise(0.14, 'highpass', 900, 0.7, 0.15); break;
      case 'land': this.noise(0.2, 'lowpass', 380, 0.8, 0.28); this.tone(62, 0.18, 'sine', 0.16, 0.6); break;
      case 'gas': this.noise(0.25, 'highpass', 1200, 0.5, 0.11); break;
      case 'hurt': this.tone(130, 0.3, 'sawtooth', 0.18, 0.45); this.noise(0.25, 'lowpass', 500, 0.7, 0.25); break;
      case 'roar': this.tone(72, 1.1, 'sawtooth', 0.2, 0.55); this.noise(1.0, 'lowpass', 320, 0.9, 0.24); break;
      case 'death': this.noise(1.2, 'lowpass', 600, 0.7, 0.22); this.tone(80, 1.0, 'sine', 0.1, 0.4); break;
      case 'coin': this.tone(880, 0.07, 'triangle', 0.09, 1.4); setTimeout(() => this.tone(1320, 0.1, 'triangle', 0.07, 1.1), 50); break;
      case 'upgrade': [440, 660, 880].forEach((f, i) => setTimeout(() => this.tone(f, 0.14, 'triangle', 0.09, 1.1), i * 70)); break;
      case 'lock': this.tone(980, 0.06, 'square', 0.06, 0.7); setTimeout(() => this.tone(720, 0.06, 'square', 0.05, 0.7), 60); break;
      case 'wave': this.tone(180, 0.5, 'sawtooth', 0.12, 1.8); this.tone(90, 0.6, 'sine', 0.16, 1.2); break;
      case 'rescue': [523, 659, 784].forEach((f, i) => setTimeout(() => this.tone(f, 0.2, 'sine', 0.08, 1.1), i * 90)); break;
      case 'dodge': this.noise(0.18, 'bandpass', 800, 0.7, 0.13); break;
      default: break;
    }
  }
  step() { this.play('step'); }
}

import { clamp } from './config.js';

const ACTION_KEYS = {
  Space: 'jump',
  ShiftLeft: 'boost', ShiftRight: 'boost',
  KeyJ: 'attack',
  KeyK: 'hook',
  KeyL: 'lock',
  Tab: 'lock',
  KeyQ: 'dodge',
  KeyE: 'interact',
  KeyP: 'pause', Escape: 'pause'
};

export class Input {
  constructor() {
    this.keys = new Set();
    this.down = {};
    this.pressed = {};
    this.move = { x: 0, y: 0 };
    this.joy = { x: 0, y: 0, active: false, id: null };
    this.look = { x: 0, y: 0 };
    this.pointerLocked = false;
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window || innerWidth < 820;
    this.enabled = false;
    this.cameraDrag = null;
    this.onPause = null;
    this.onFirstGesture = null;
    this.gestured = false;
    this.attach();
    document.body.classList.toggle('touch', this.isTouch);
  }

  attach() {
    const canvas = document.getElementById('scene');
    const joy = document.getElementById('joystick');
    const knob = document.getElementById('joy-knob');

    window.addEventListener('keydown', (e) => {
      if (!this.enabled) return;
      const action = ACTION_KEYS[e.code];
      if (e.code === 'Tab' || e.code === 'Space' || e.code.startsWith('Arrow')) e.preventDefault();
      if (action) {
        if (action === 'pause') { this.onPause?.(); return; }
        if (!this.down[action]) this.pressed[action] = true;
        this.down[action] = true;
      }
      this.keys.add(e.code);
    }, { passive: false });
    window.addEventListener('keyup', (e) => {
      const action = ACTION_KEYS[e.code];
      if (action) this.down[action] = false;
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      for (const k of Object.keys(this.down)) this.down[k] = false;
    });

    // Mouse look / pointer lock
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === canvas;
      if (!this.pointerLocked && this.enabled && !this.isTouch) this.onPause?.();
    });
    canvas.addEventListener('mousedown', (e) => {
      if (!this.enabled || this.isTouch) return;
      if (!this.pointerLocked) {
        canvas.requestPointerLock?.();
        return;
      }
      if (e.button === 0) this.trigger('attack');
      if (e.button === 2) this.trigger('hook');
    });
    window.addEventListener('mousemove', (e) => {
      if (!this.enabled || !this.pointerLocked) return;
      this.look.x += e.movementX;
      this.look.y += e.movementY;
    });
    window.addEventListener('contextmenu', (e) => e.preventDefault());
    window.addEventListener('wheel', (e) => {
      if (!this.enabled) return;
      this.wheel = clamp((this.wheel || 0) + Math.sign(e.deltaY), -2, 2);
    }, { passive: true });

    // Touch camera drag anywhere on the canvas / right side
    const startCamera = (e) => {
      if (!this.enabled || !this.isTouch) return;
      if (e.target.closest && e.target.closest('button, .joystick, .dialogue, .overlay-card')) return;
      this.cameraDrag = { id: e.pointerId, x: e.clientX, y: e.clientY };
      canvas.setPointerCapture?.(e.pointerId);
    };
    const moveCamera = (e) => {
      if (!this.cameraDrag || this.cameraDrag.id !== e.pointerId) return;
      this.look.x += (e.clientX - this.cameraDrag.x) * 1.55;
      this.look.y += (e.clientY - this.cameraDrag.y) * 1.55;
      this.cameraDrag.x = e.clientX; this.cameraDrag.y = e.clientY;
    };
    const endCamera = (e) => {
      if (this.cameraDrag && this.cameraDrag.id === e.pointerId) this.cameraDrag = null;
    };
    canvas.addEventListener('pointerdown', startCamera);
    window.addEventListener('pointermove', moveCamera);
    window.addEventListener('pointerup', endCamera);
    window.addEventListener('pointercancel', endCamera);

    // Joystick
    const joyMove = (e) => {
      if (this.joy.id !== e.pointerId) return;
      const r = joy.getBoundingClientRect();
      const cx = r.left + r.width / 2;
      const cy = r.bottom - 18 - 64;
      let dx = e.clientX - cx;
      let dy = e.clientY - cy;
      const max = 46;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = dx / len * max; dy = dy / len * max; }
      this.joy.x = dx / max; this.joy.y = dy / max;
      this.joy.active = true;
      knob.style.transform = `translate(${dx}px,${dy}px)`;
    };
    const joyEnd = (e) => {
      if (this.joy.id !== e.pointerId) return;
      this.joy.id = null; this.joy.x = 0; this.joy.y = 0; this.joy.active = false;
      knob.style.transform = 'translate(0,0)';
    };
    joy.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault(); e.stopPropagation();
      this.joy.id = e.pointerId;
      joy.setPointerCapture?.(e.pointerId);
      joyMove(e);
    });
    joy.addEventListener('pointermove', joyMove);
    joy.addEventListener('pointerup', joyEnd);
    joy.addEventListener('pointercancel', joyEnd);

    // Touch action buttons
    document.querySelectorAll('[data-action]').forEach(btn => {
      const action = btn.dataset.action;
      btn.addEventListener('pointerdown', (e) => {
        if (!this.enabled) return;
        e.preventDefault(); e.stopPropagation();
        btn.classList.add('pressed');
        this.trigger(action);
        btn.setPointerCapture?.(e.pointerId);
      });
      const up = (e) => { btn.classList.remove('pressed'); };
      btn.addEventListener('pointerup', up);
      btn.addEventListener('pointercancel', up);
      btn.addEventListener('pointerleave', up);
    });

    const gesture = () => {
      if (this.gestured) return;
      this.gestured = true;
      this.onFirstGesture?.();
    };
    window.addEventListener('pointerdown', gesture, { once: true });
    window.addEventListener('keydown', gesture, { once: true });
    window.addEventListener('touchstart', gesture, { once: true, passive: true });
  }

  trigger(action) {
    if (!this.enabled) return;
    if (!this.down[action]) this.pressed[action] = true;
    this.down[action] = true;
    if (action === 'jump' || action === 'attack' || action === 'hook' || action === 'dodge' || action === 'lock' || action === 'interact') {
      setTimeout(() => { this.down[action] = false; }, 90);
    }
  }

  consume(action) {
    if (this.pressed[action]) { this.pressed[action] = false; return true; }
    return false;
  }
  consumeLook() {
    const l = { x: this.look.x, y: this.look.y };
    this.look.x = 0; this.look.y = 0;
    return l;
  }
  consumeWheel() {
    const w = this.wheel || 0; this.wheel = 0; return w;
  }
  get moveVector() {
    let x = this.joy.x;
    let y = this.joy.y;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y = -1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y = 1;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x = -1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x = 1;
    if (this.keys.has('KeyW') && this.keys.has('KeyA')) { x = -0.707; y = -0.707; }
    if (this.keys.has('KeyW') && this.keys.has('KeyD')) { x = 0.707; y = -0.707; }
    if (this.keys.has('KeyS') && this.keys.has('KeyA')) { x = -0.707; y = 0.707; }
    if (this.keys.has('KeyS') && this.keys.has('KeyD')) { x = 0.707; y = 0.707; }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    return { x, y, len: Math.min(1, len) };
  }
  get sprint() { return this.down.boost; }
  requestLock(canvas) {
    if (!this.isTouch && this.enabled) canvas?.requestPointerLock?.();
  }
  exitLock() {
    if (document.pointerLockElement) document.exitPointerLock?.();
  }
  clear() {
    this.keys.clear();
    for (const k of Object.keys(this.down)) this.down[k] = false;
    for (const k of Object.keys(this.pressed)) this.pressed[k] = false;
    this.joy.x = 0; this.joy.y = 0; this.joy.active = false; this.joy.id = null;
    document.getElementById('joy-knob').style.transform = 'translate(0,0)';
  }
}

import * as THREE from '../vendor/three/three.module.min.js';
import { QUALITY, ZONES, rand, randInt, pick, clamp } from './config.js';

const MAP = 1400;
const HALF = MAP / 2;
const CITY = { x1: -210, x2: 210, z1: -180, z2: 180 };
const WALL_H = 26;

function canvasTexture(size, draw) {
  const c = document.createElement('canvas');
  c.width = size; c.height = size;
  const ctx = c.getContext('2d');
  draw(ctx, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function makeFacadeTexture() {
  return canvasTexture(128, (ctx, s) => {
    ctx.fillStyle = '#9aa0a3'; ctx.fillRect(0, 0, s, s);
    ctx.fillStyle = 'rgba(0,0,0,.12)';
    for (let y = 0; y < s; y += 16) ctx.fillRect(0, y, s, 2);
    for (let y = 6; y < s - 8; y += 16) {
      for (let x = 8; x < s - 8; x += 18) {
        const lit = Math.random() < 0.28;
        ctx.fillStyle = lit ? 'rgba(255,214,148,.72)' : 'rgba(36,44,50,.82)';
        ctx.fillRect(x, y, 9, 7);
      }
    }
    ctx.fillStyle = 'rgba(255,255,255,.08)';
    for (let x = 0; x < s; x += 32) ctx.fillRect(x, 0, 1, s);
  });
}

function makeStoneTexture() {
  return canvasTexture(128, (ctx, s) => {
    ctx.fillStyle = '#9d988b'; ctx.fillRect(0, 0, s, s);
    ctx.strokeStyle = 'rgba(55,52,46,.45)'; ctx.lineWidth = 2;
    for (let y = 0; y < s; y += 16) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(s, y); ctx.stroke();
      const off = (y / 16) % 2 ? 16 : 0;
      for (let x = off; x < s; x += 32) {
        ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x, y + 16); ctx.stroke();
      }
    }
    for (let i = 0; i < 160; i++) {
      ctx.fillStyle = `rgba(${randInt(40, 80)},${randInt(38, 70)},${randInt(32, 60)},${rand(.03, .12)})`;
      ctx.fillRect(rand(0, s), rand(0, s), rand(1, 7), rand(1, 5));
    }
  });
}

function makeGroundTexture(quality) {
  const size = quality === 'low' ? 1024 : 2048;
  const tex = canvasTexture(size, (ctx, s) => {
    const px = x => (x + HALF) / MAP * s;
    const pz = z => (z + HALF) / MAP * s;
    // base grassland
    const g = ctx.createLinearGradient(0, 0, s, s);
    g.addColorStop(0, '#6c8450'); g.addColorStop(.45, '#768d58'); g.addColorStop(1, '#647c4b');
    ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);

    // wasteland west
    const wg = ctx.createLinearGradient(0, 0, px(-180), 0);
    wg.addColorStop(0, '#9c7a54'); wg.addColorStop(.7, '#a9855e'); wg.addColorStop(1, 'rgba(155,122,84,0)');
    ctx.fillStyle = wg; ctx.fillRect(0, 0, px(-180), s);
    for (let i = 0; i < 380; i++) {
      const x = rand(0, px(-180)), y = rand(0, s);
      ctx.fillStyle = `rgba(${randInt(80, 150)},${randInt(60, 110)},${randInt(40, 80)},${rand(.03, .14)})`;
      ctx.beginPath(); ctx.ellipse(x, y, rand(6, 42), rand(4, 24), rand(0, 6.3), 0, 6.3); ctx.fill();
    }

    // forest north-east
    ctx.fillStyle = 'rgba(45,74,45,.55)';
    ctx.fillRect(px(0), 0, s - px(0), pz(-195));
    for (let i = 0; i < 260; i++) {
      const x = rand(px(0), s), y = rand(0, pz(-195));
      ctx.fillStyle = `rgba(${randInt(35, 68)},${randInt(60, 95)},${randInt(35, 62)},${rand(.04, .16)})`;
      ctx.beginPath(); ctx.arc(x, y, rand(8, 40), 0, 6.3); ctx.fill();
    }

    // city slab
    ctx.fillStyle = '#7c8081';
    ctx.fillRect(px(CITY.x1), pz(CITY.z1), px(CITY.x2) - px(CITY.x1), pz(CITY.z2) - pz(CITY.z1));
    ctx.fillStyle = 'rgba(30,32,34,.13)';
    for (let i = 0; i < 500; i++) ctx.fillRect(rand(px(CITY.x1), px(CITY.x2)), rand(pz(CITY.z1), pz(CITY.z2)), rand(2, 12), rand(2, 8));

    // city roads
    ctx.strokeStyle = '#4b4f52'; ctx.lineWidth = Math.max(6, s / 120);
    for (let x = -200; x <= 200; x += 34) {
      ctx.beginPath(); ctx.moveTo(px(x), pz(CITY.z1)); ctx.lineTo(px(x), pz(CITY.z2)); ctx.stroke();
    }
    for (let z = -170; z <= 170; z += 34) {
      ctx.beginPath(); ctx.moveTo(px(CITY.x1), pz(z)); ctx.lineTo(px(CITY.x2), pz(z)); ctx.stroke();
    }
    ctx.strokeStyle = '#55595b'; ctx.lineWidth = Math.max(12, s / 62);
    ctx.beginPath(); ctx.moveTo(px(0), pz(CITY.z1)); ctx.lineTo(px(0), pz(CITY.z2)); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(px(CITY.x1), pz(20)); ctx.lineTo(px(CITY.x2), pz(20)); ctx.stroke();

    // plaza
    ctx.fillStyle = '#8d8f8a';
    ctx.beginPath(); ctx.arc(px(0), pz(20), (38 / MAP) * s, 0, 6.3); ctx.fill();
    ctx.strokeStyle = 'rgba(50,50,48,.35)'; ctx.lineWidth = 2;
    for (let r = 8; r < 36; r += 7) { ctx.beginPath(); ctx.arc(px(0), pz(20), (r / MAP) * s, 0, 6.3); ctx.stroke(); }

    // south road out of gate
    ctx.strokeStyle = '#6b6150'; ctx.lineWidth = Math.max(12, s / 70);
    ctx.beginPath(); ctx.moveTo(px(0), pz(CITY.z2)); ctx.lineTo(px(0), s); ctx.stroke();
    ctx.strokeStyle = 'rgba(70,62,48,.5)'; ctx.lineWidth = Math.max(4, s / 220);
    ctx.beginPath(); ctx.moveTo(px(0), pz(CITY.z2)); ctx.lineTo(px(0), s); ctx.stroke();

    // forest trails
    ctx.strokeStyle = 'rgba(100,82,58,.55)'; ctx.lineWidth = Math.max(4, s / 260);
    ctx.beginPath(); ctx.moveTo(px(20), pz(-190)); ctx.quadraticCurveTo(px(100), pz(-300), px(160), pz(-430)); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(px(160), pz(-430)); ctx.quadraticCurveTo(px(260), pz(-460), px(420), pz(-420)); ctx.stroke();

    // grass speckles
    for (let i = 0; i < 2600; i++) {
      const x = rand(0, s), y = rand(0, s);
      ctx.fillStyle = `rgba(${randInt(60, 130)},${randInt(80, 150)},${randInt(45, 90)},${rand(.04, .16)})`;
      ctx.fillRect(x, y, rand(1, 4), rand(1, 4));
    }
  });
  tex.anisotropy = 8;
  return tex;
}

function makeSky() {
  const geo = new THREE.SphereGeometry(1800, 24, 14);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: {
      top: { value: new THREE.Color(0x2d4a63) },
      mid: { value: new THREE.Color(0x8fa6ae) },
      bottom: { value: new THREE.Color(0xd6c5a8) },
      sunDir: { value: new THREE.Vector3(0.5, 0.42, 0.35).normalize() }
    },
    vertexShader: `varying vec3 vP; void main(){ vP=position; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }`,
    fragmentShader: `varying vec3 vP; uniform vec3 top,mid,bottom,sunDir;
      void main(){ vec3 d=normalize(vP); float h=clamp(d.y*1.15+.02,0.,1.);
      vec3 c=mix(bottom,mid,smoothstep(0.,.3,h)); c=mix(c,top,smoothstep(.22,.9,h));
      float sun=pow(max(dot(d,normalize(sunDir)),0.),180.); c+=vec3(1.,.82,.55)*sun*.55;
      float haze=pow(1.-abs(d.y),8.)*.08; c+=vec3(.9,.8,.65)*haze;
      gl_FragColor=vec4(c,1.); }`
  });
  return new THREE.Mesh(geo, mat);
}

export class World {
  constructor(scene, renderer, qualityKey = 'high') {
    this.scene = scene;
    this.renderer = renderer;
    this.qualityKey = qualityKey;
    this.colliders = [];
    this.anchors = [];
    this.trees = [];
    this.gate = null;
    this.clouds = [];
    this.dust = null;
    this.time = 0;
    this.build();
  }

  build() {
    const q = QUALITY[this.qualityKey] || QUALITY.high;
    this.q = q;
    this.scene.fog = new THREE.Fog(0xaeb9b4, q.fog[0], q.fog[1]);
    this.scene.background = new THREE.Color(0x9fb1b4);
    this.scene.add(makeSky());

    // lights
    const hemi = new THREE.HemisphereLight(0xc4d6e4, 0x4d4634, 1.35);
    this.scene.add(hemi);
    const sun = new THREE.DirectionalLight(0xffe0b6, 2.25);
    sun.position.set(220, 300, 150);
    sun.castShadow = q.shadows;
    if (q.shadows) {
      sun.shadow.mapSize.set(q.shadowSize, q.shadowSize);
      sun.shadow.camera.near = 20;
      sun.shadow.camera.far = 900;
      const s = 330;
      sun.shadow.camera.left = -s; sun.shadow.camera.right = s;
      sun.shadow.camera.top = s; sun.shadow.camera.bottom = -s;
      sun.shadow.bias = -0.0007;
      sun.shadow.normalBias = 0.35;
    }
    this.scene.add(sun);
    this.sun = sun;
    this.hemi = hemi;

    // ground
    const groundTex = makeGroundTexture(this.qualityKey);
    const groundMat = new THREE.MeshLambertMaterial({ map: groundTex, color: 0xffffff });
    const ground = new THREE.Mesh(new THREE.PlaneGeometry(MAP, MAP), groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.receiveShadow = q.shadows;
    this.scene.add(ground);
    this.ground = ground;

    // distant mountains
    const mountainMat = new THREE.MeshLambertMaterial({ color: 0x6e8084, flatShading: true });
    const mountCount = this.qualityKey === 'low' ? 12 : 22;
    for (let i = 0; i < mountCount; i++) {
      const a = (i / mountCount) * Math.PI * 2 + rand(-.08, .08);
      const r = rand(800, 1080);
      const h = rand(90, 250);
      const m = new THREE.Mesh(new THREE.ConeGeometry(rand(100, 240), h, 5), mountainMat);
      m.position.set(Math.cos(a) * r, h / 2 - 8, Math.sin(a) * r);
      m.rotation.y = rand(0, 6.3);
      this.scene.add(m);
    }

    this.buildCity(q);
    this.buildWalls(q);
    this.buildForest(q);
    this.buildGrass(q);
    this.buildWasteland(q);
    this.buildClouds(q);

    // ambient dust in wasteland
    if (q.dust > 0) {
      const pos = new Float32Array(q.dust * 3);
      for (let i = 0; i < q.dust; i++) {
        pos[i * 3] = rand(-620, -230);
        pos[i * 3 + 1] = rand(0.4, 12);
        pos[i * 3 + 2] = rand(-600, 600);
      }
      const g = new THREE.BufferGeometry();
      g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      const m = new THREE.PointsMaterial({ color: 0xd3b58d, size: 0.55, transparent: true, opacity: 0.5, depthWrite: false });
      this.dust = new THREE.Points(g, m);
      this.scene.add(this.dust);
    }
  }

  buildCity(q) {
    const facade = makeFacadeTexture();
    const mat = new THREE.MeshStandardMaterial({ map: facade, roughness: 0.86, metalness: 0.04, vertexColors: true });
    const geo = new THREE.BoxGeometry(1, 1, 1);
    const maxBuildings = q.buildings;
    const placements = [];
    for (let gx = -5; gx <= 5; gx++) {
      for (let gz = -4; gz <= 4; gz++) {
        if (gx === 0 && gz === 0) continue;
        const cx = gx * 36 + rand(-3, 3);
        const cz = gz * 36 + rand(-3, 3) + 15;
        if (cz > 128 && Math.abs(cx) < 30) continue;
        if (Math.abs(cx) < 16 && Math.abs(cz - 20) < 26) continue;
        const n = Math.random() < 0.34 ? 2 : 1;
        for (let k = 0; k < n; k++) {
          const w = rand(13, 24), d = rand(13, 23);
          const px = cx + (n === 2 ? (k ? 10 : -10) : 0) + rand(-1, 1);
          const pz = cz + rand(-2, 2);
          const landmark = Math.abs(gx) <= 2 && Math.abs(gz) <= 2 && Math.random() < 0.14;
          const h = landmark ? rand(48, 86) : rand(9, 34);
          placements.push({ x: px, z: pz, w, d, h });
          if (placements.length >= maxBuildings) break;
        }
        if (placements.length >= maxBuildings) break;
      }
      if (placements.length >= maxBuildings) break;
    }
    // guarantee a couple of towers near center for ODM
    placements.push({ x: -58, z: 4, w: 20, d: 20, h: 68 });
    placements.push({ x: 62, z: -46, w: 18, d: 22, h: 74 });
    placements.push({ x: -78, z: -96, w: 22, d: 18, h: 56 });

    const mesh = new THREE.InstancedMesh(geo, mat, placements.length);
    mesh.castShadow = q.shadows;
    mesh.receiveShadow = q.shadows;
    const m4 = new THREE.Matrix4();
    const col = new THREE.Color();
    const palette = [0x9b9488, 0xa8a093, 0x8c8f8b, 0xb0a89a, 0x938f86, 0xa39b8b];
    placements.forEach((b, i) => {
      m4.makeScale(b.w, b.h, b.d);
      m4.setPosition(b.x, b.h / 2, b.z);
      mesh.setMatrixAt(i, m4);
      col.setHex(pick(palette)).multiplyScalar(rand(.88, 1.06));
      mesh.setColorAt(i, col);
      const c = {
        minX: b.x - b.w / 2, maxX: b.x + b.w / 2,
        minZ: b.z - b.d / 2, maxZ: b.z + b.d / 2,
        top: b.h, type: 'building'
      };
      this.colliders.push(c);
      this.anchors.push(
        new THREE.Vector3(b.x, b.h + 0.5, b.z),
        new THREE.Vector3(b.x - b.w / 2, b.h + 0.5, b.z - b.d / 2),
        new THREE.Vector3(b.x + b.w / 2, b.h + 0.5, b.z + b.d / 2),
        new THREE.Vector3(b.x - b.w / 2, b.h + 0.5, b.z + b.d / 2),
        new THREE.Vector3(b.x + b.w / 2, b.h + 0.5, b.z - b.d / 2)
      );
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    this.scene.add(mesh);
    this.cityMesh = mesh;

    // rooftop water tanks / chimneys for silhouette
    const tankGeo = new THREE.CylinderGeometry(1.4, 1.4, 3.4, 6);
    const tankMat = new THREE.MeshLambertMaterial({ color: 0x5c5145 });
    const tanks = new THREE.InstancedMesh(tankGeo, tankMat, Math.min(70, placements.length));
    let ti = 0;
    for (const b of placements) {
      if (ti >= tanks.count) break;
      if (b.h > 30 || Math.random() < 0.35) {
        m4.makeTranslation(b.x + rand(-3, 3), b.h + 1.7, b.z + rand(-3, 3));
        tanks.setMatrixAt(ti++, m4);
      }
    }
    tanks.count = ti;
    tanks.instanceMatrix.needsUpdate = true;
    tanks.castShadow = q.shadows;
    this.scene.add(tanks);
    this.tanks = tanks;

    // street props: crates and lamps
    const crateGeo = new THREE.BoxGeometry(1.6, 1.6, 1.6);
    const crateMat = new THREE.MeshLambertMaterial({ color: 0x71563c });
    const crates = new THREE.InstancedMesh(crateGeo, crateMat, 60);
    for (let i = 0; i < crates.count; i++) {
      m4.makeRotationY(rand(0, 6.3));
      m4.setPosition(rand(-190, 190), 0.8, rand(-160, 160));
      crates.setMatrixAt(i, m4);
    }
    crates.instanceMatrix.needsUpdate = true;
    crates.castShadow = q.shadows;
    this.scene.add(crates);

    const lampGeo = new THREE.CylinderGeometry(0.12, 0.15, 6, 5);
    const lampMat = new THREE.MeshLambertMaterial({ color: 0x3b3a36 });
    const lamps = new THREE.InstancedMesh(lampGeo, lampMat, 40);
    for (let i = 0; i < lamps.count; i++) {
      m4.makeTranslation(rand(-190, 190), 3, rand(-150, 150));
      lamps.setMatrixAt(i, m4);
    }
    lamps.instanceMatrix.needsUpdate = true;
    this.scene.add(lamps);
  }

  addBox(collider, mat, shadow) {
    const w = collider.maxX - collider.minX;
    const d = collider.maxZ - collider.minZ;
    const h = collider.top;
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    mesh.position.set((collider.minX + collider.maxX) / 2, h / 2, (collider.minZ + collider.maxZ) / 2);
    mesh.castShadow = shadow; mesh.receiveShadow = shadow;
    this.scene.add(mesh);
    return mesh;
  }

  buildWalls(q) {
    const stone = makeStoneTexture();
    stone.wrapS = stone.wrapT = THREE.RepeatWrapping;
    stone.repeat.set(3, 1.4);
    const mat = new THREE.MeshStandardMaterial({ map: stone, color: 0xbdb6a6, roughness: 0.95, metalness: 0.02 });
    const T = 7;
    const segments = [
      { minX: -210, maxX: 210, minZ: -183, maxZ: -176, top: WALL_H }, // north
      { minX: -210, maxX: -12, minZ: 176, maxZ: 183, top: WALL_H },   // south west
      { minX: 12, maxX: 210, minZ: 176, maxZ: 183, top: WALL_H },     // south east
      { minX: 206, maxX: 213, minZ: -176, maxZ: 176, top: WALL_H },   // east
      { minX: -213, maxX: -206, minZ: -176, maxZ: 176, top: WALL_H }  // west
    ];
    for (const s of segments) {
      this.colliders.push({ ...s, type: 'wall' });
      this.addBox(s, mat, q.shadows);
    }
    // anchors along wall
    for (let x = -200; x <= 200; x += 18) {
      this.anchors.push(new THREE.Vector3(x, WALL_H + 1, -180));
      if (Math.abs(x) > 14) this.anchors.push(new THREE.Vector3(x, WALL_H + 1, 180));
    }
    for (let z = -170; z <= 170; z += 18) {
      this.anchors.push(new THREE.Vector3(210, WALL_H + 1, z));
      this.anchors.push(new THREE.Vector3(-210, WALL_H + 1, z));
    }
    // battlements
    const merlonGeo = new THREE.BoxGeometry(3, 2.4, 3.2);
    const merlonMat = new THREE.MeshLambertMaterial({ color: 0xa9a292 });
    const spots = [];
    for (let x = -205; x <= 205; x += 7) {
      spots.push([x, -180]); if (Math.abs(x) > 14) spots.push([x, 180]);
    }
    for (let z = -172; z <= 172; z += 7) { spots.push([210, z]); spots.push([-210, z]); }
    const merlons = new THREE.InstancedMesh(merlonGeo, merlonMat, spots.length);
    const m4 = new THREE.Matrix4();
    spots.forEach((p, i) => { m4.makeTranslation(p[0], WALL_H + 1.2, p[1]); merlons.setMatrixAt(i, m4); });
    merlons.instanceMatrix.needsUpdate = true;
    merlons.castShadow = q.shadows;
    this.scene.add(merlons);

    // gate
    const gateGroup = new THREE.Group();
    const gateMat = new THREE.MeshStandardMaterial({ color: 0x4b3524, roughness: 0.8, metalness: 0.25 });
    const door = new THREE.Mesh(new THREE.BoxGeometry(24, 17, 1.6), gateMat);
    door.position.set(0, 8.5, 180);
    door.castShadow = q.shadows;
    gateGroup.add(door);
    const barMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, metalness: 0.7, roughness: 0.45 });
    for (let i = -9; i <= 9; i += 3) {
      const bar = new THREE.Mesh(new THREE.BoxGeometry(0.45, 16, 0.5), barMat);
      bar.position.set(i, 8.4, 180.9);
      gateGroup.add(bar);
    }
    const arch = new THREE.Mesh(new THREE.BoxGeometry(30, 3, 3), mat);
    arch.position.set(0, 18.5, 180);
    gateGroup.add(arch);
    this.scene.add(gateGroup);
    const gateCol = { minX: -12, maxX: 12, minZ: 177.5, maxZ: 182.5, top: 17, type: 'gate' };
    this.colliders.push(gateCol);
    this.gate = {
      group: gateGroup, door, collider: gateCol, hp: 100, maxHp: 100,
      position: new THREE.Vector3(0, 0, 180), alive: true
    };
    // banners
    const bannerMat = new THREE.MeshLambertMaterial({ color: 0x8e2a22, side: THREE.DoubleSide });
    for (const sx of [-30, 30]) {
      const banner = new THREE.Mesh(new THREE.PlaneGeometry(6, 11), bannerMat);
      banner.position.set(sx, 13, 176.4);
      this.scene.add(banner);
    }
  }

  buildForest(q) {
    const count = q.trees;
    const trunkGeo = new THREE.CylinderGeometry(0.55, 0.85, 8, 5);
    const trunkMat = new THREE.MeshLambertMaterial({ color: 0x4b3826 });
    const canopyGeo = new THREE.IcosahedronGeometry(1, 0);
    const canopyMat = new THREE.MeshLambertMaterial({ color: 0x395c35, flatShading: true });
    const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, count);
    const canopies = new THREE.InstancedMesh(canopyGeo, canopyMat, count);
    const m4 = new THREE.Matrix4();
    const col = new THREE.Color();
    const qrot = new THREE.Quaternion();
    const e = new THREE.Euler();
    const scale = new THREE.Vector3();
    let idx = 0;
    let guard = 0;
    while (idx < count && guard++ < count * 12) {
      let x, z;
      if (Math.random() < 0.78) { x = rand(-10, 570); z = rand(-600, -215); }
      else { x = rand(250, 590); z = rand(-180, 560); }
      if (x > -230 && x < 230 && z > -200 && z < 200) continue;
      const h = rand(0.8, 1.55);
      const cr = rand(2.4, 4.8) * h;
      e.set(0, rand(0, 6.3), 0);
      qrot.setFromEuler(e);
      scale.set(h, h, h);
      m4.compose(new THREE.Vector3(x, 4 * h, z), qrot, scale);
      trunks.setMatrixAt(idx, m4);
      m4.compose(new THREE.Vector3(x, 8 * h + cr * 0.35, z), qrot, new THREE.Vector3(cr, cr * rand(.9, 1.3), cr));
      canopies.setMatrixAt(idx, m4);
      col.setHex(pick([0x35582f, 0x3f6636, 0x2f4d2c, 0x466c3a])).multiplyScalar(rand(.88, 1.08));
      canopies.setColorAt(idx, col);
      this.colliders.push({ minX: x - 1.1, maxX: x + 1.1, minZ: z - 1.1, maxZ: z + 1.1, top: 6 * h, type: 'tree' });
      this.trees.push({ x, z, h });
      if (idx % 2 === 0) this.anchors.push(new THREE.Vector3(x, 8 * h + cr, z));
      idx++;
    }
    trunks.count = idx; canopies.count = idx;
    trunks.instanceMatrix.needsUpdate = true; canopies.instanceMatrix.needsUpdate = true;
    if (canopies.instanceColor) canopies.instanceColor.needsUpdate = true;
    trunks.castShadow = q.shadows; canopies.castShadow = q.shadows;
    trunks.receiveShadow = q.shadows; canopies.receiveShadow = q.shadows;
    this.scene.add(trunks, canopies);
    this.trunks = trunks; this.canopies = canopies;
  }

  buildGrass(q) {
    if (q.grass <= 0) return;
    const geo = new THREE.ConeGeometry(0.16, 1.35, 3);
    geo.translate(0, 0.67, 0);
    const mat = new THREE.MeshLambertMaterial({ color: 0x7d9a52, flatShading: true, side: THREE.DoubleSide });
    const mesh = new THREE.InstancedMesh(geo, mat, q.grass);
    const m4 = new THREE.Matrix4();
    const col = new THREE.Color();
    const e = new THREE.Euler();
    const qr = new THREE.Quaternion();
    const sc = new THREE.Vector3();
    for (let i = 0; i < q.grass; i++) {
      let x, z;
      if (Math.random() < 0.55) { x = rand(230, 610); z = rand(-150, 610); }
      else if (Math.random() < 0.5) { x = rand(-600, 610); z = rand(210, 610); }
      else { x = rand(-600, 610); z = rand(-600, -190); }
      if (x > -220 && x < 220 && z > -190 && z < 190) { x = rand(230, 500); z = rand(-100, 500); }
      const s = rand(0.6, 1.5);
      e.set(rand(-.16, .16), rand(0, 6.3), rand(-.16, .16));
      qr.setFromEuler(e); sc.set(s, s * rand(.8, 1.5), s);
      m4.compose(new THREE.Vector3(x, 0, z), qr, sc);
      mesh.setMatrixAt(i, m4);
      col.setHex(pick([0x7d9a52, 0x8da95c, 0x6f8c49, 0x91a965]));
      mesh.setColorAt(i, col);
    }
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.receiveShadow = q.grassShadows;
    this.scene.add(mesh);
    this.grassMesh = mesh;
  }

  buildWasteland(q) {
    const count = q.rocks;
    const geo = new THREE.DodecahedronGeometry(1, 0);
    const mat = new THREE.MeshLambertMaterial({ color: 0x8a7460, flatShading: true });
    const rocks = new THREE.InstancedMesh(geo, mat, count);
    const m4 = new THREE.Matrix4();
    const col = new THREE.Color();
    const e = new THREE.Euler();
    const qr = new THREE.Quaternion();
    for (let i = 0; i < count; i++) {
      const x = rand(-620, -240);
      const z = rand(-600, 600);
      const s = rand(1.2, 7);
      e.set(rand(0, 3), rand(0, 6.3), rand(0, 3));
      qr.setFromEuler(e);
      m4.compose(new THREE.Vector3(x, s * 0.34, z), qr, new THREE.Vector3(s, s * rand(.4, .9), s));
      rocks.setMatrixAt(i, m4);
      col.setHex(pick([0x806b57, 0x937c65, 0x74604f, 0x9b846b]));
      rocks.setColorAt(i, col);
      if (s > 3.2) this.colliders.push({ minX: x - s * .55, maxX: x + s * .55, minZ: z - s * .55, maxZ: z + s * .55, top: s * .8, type: 'rock' });
    }
    rocks.instanceMatrix.needsUpdate = true;
    if (rocks.instanceColor) rocks.instanceColor.needsUpdate = true;
    rocks.castShadow = q.shadows;
    this.scene.add(rocks);
    this.rocks = rocks;

    // ruined walls
    const ruinMat = new THREE.MeshStandardMaterial({ color: 0x726b5f, roughness: 1 });
    const ruins = [];
    for (let i = 0; i < 18; i++) {
      const x = rand(-600, -250), z = rand(-560, 560);
      const w = rand(6, 20), d = rand(2, 5), h = rand(3, 15);
      ruins.push({ x, z, w, d, h });
    }
    const ruinMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), ruinMat, ruins.length);
    ruins.forEach((r, i) => {
      m4.makeScale(r.w, r.h, r.d);
      m4.setPosition(r.x, r.h / 2, r.z);
      ruinMesh.setMatrixAt(i, m4);
      this.colliders.push({ minX: r.x - r.w / 2, maxX: r.x + r.w / 2, minZ: r.z - r.d / 2, maxZ: r.z + r.d / 2, top: r.h, type: 'ruin' });
      this.anchors.push(new THREE.Vector3(r.x, r.h + .5, r.z));
    });
    ruinMesh.instanceMatrix.needsUpdate = true;
    ruinMesh.castShadow = q.shadows;
    this.scene.add(ruinMesh);
  }

  buildClouds(q) {
    const size = 128;
    const tex = canvasTexture(size, (ctx, s) => {
      const g = ctx.createRadialGradient(s / 2, s / 2, 2, s / 2, s / 2, s / 2);
      g.addColorStop(0, 'rgba(255,255,255,.9)');
      g.addColorStop(.45, 'rgba(255,255,255,.4)');
      g.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, s, s);
    });
    const n = this.qualityKey === 'low' ? 6 : 14;
    for (let i = 0; i < n; i++) {
      const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, opacity: rand(.13, .26), depthWrite: false, fog: false });
      const sp = new THREE.Sprite(mat);
      sp.position.set(rand(-900, 900), rand(130, 260), rand(-900, 900));
      sp.scale.set(rand(140, 360), rand(40, 100), 1);
      this.scene.add(sp);
      this.clouds.push(sp);
    }
  }

  update(dt) {
    this.time += dt;
    if (this.dust) this.dust.rotation.y += dt * 0.004;
    for (const c of this.clouds) {
      c.position.x += dt * 1.1;
      if (c.position.x > 1000) c.position.x = -1000;
    }
  }

  // --- collision helpers ---
  groundHeightAt(x, z, radius = 0.32) {
    let h = 0;
    for (const c of this.colliders) {
      if (x + radius < c.minX || x - radius > c.maxX || z + radius < c.minZ || z - radius > c.maxZ) continue;
      if (c.top > h) h = c.top;
    }
    return h;
  }

  resolveCircle(pos, radius = 0.55) {
    let hit = false;
    for (const c of this.colliders) {
      if (pos.y >= c.top - 0.15) continue;
      if (c.type === 'gate' && !this.gate?.alive) continue;
      const nx = clamp(pos.x, c.minX, c.maxX);
      const nz = clamp(pos.z, c.minZ, c.maxZ);
      let dx = pos.x - nx, dz = pos.z - nz;
      let d = Math.hypot(dx, dz);
      if (d >= radius) continue;
      hit = true;
      if (d < 0.0001) {
        // inside the box: push out along shortest axis
        const left = pos.x - c.minX, right = c.maxX - pos.x;
        const front = pos.z - c.minZ, back = c.maxZ - pos.z;
        const m = Math.min(left, right, front, back);
        if (m === left) pos.x = c.minX - radius;
        else if (m === right) pos.x = c.maxX + radius;
        else if (m === front) pos.z = c.minZ - radius;
        else pos.z = c.maxZ + radius;
      } else {
        const push = (radius - d) / d;
        pos.x += dx * push;
        pos.z += dz * push;
      }
    }
    return hit;
  }

  pointInSolid(p, pad = 0) {
    for (const c of this.colliders) {
      if (c.type === 'gate' && !this.gate?.alive) continue;
      if (p.x > c.minX - pad && p.x < c.maxX + pad && p.z > c.minZ - pad && p.z < c.maxZ + pad && p.y < c.top + pad) return true;
    }
    return false;
  }

  cameraBoom(from, to) {
    const dir = new THREE.Vector3().subVectors(to, from);
    const dist = dir.length();
    if (dist < 0.01) return to.clone();
    dir.normalize();
    const steps = 10;
    let last = from.clone();
    for (let i = 1; i <= steps; i++) {
      const p = from.clone().addScaledVector(dir, dist * i / steps);
      if (this.pointInSolid(p, 0.35)) return last;
      last = p;
    }
    return to;
  }

  findAnchor(pos, forward, range = 120, extra = []) {
    let best = null, bestScore = -Infinity;
    const all = extra.length ? this.anchors.concat(extra) : this.anchors;
    for (const a of all) {
      const dx = a.x - pos.x, dy = a.y - pos.y, dz = a.z - pos.z;
      const d = Math.hypot(dx, dy, dz);
      if (d < 5 || d > range) continue;
      if (dy < 2.5) continue;
      const inv = 1 / d;
      const dot = (dx * inv) * forward.x + (dy * inv) * forward.y + (dz * inv) * forward.z;
      if (dot < -0.12) continue;
      const score = dot * 2.4 - d / range * 1.1 + (a.y > pos.y + 10 ? 0.15 : 0);
      if (score > bestScore) { bestScore = score; best = a; }
    }
    return best;
  }

  isInsideWalls(pos) {
    return pos.x > CITY.x1 && pos.x < CITY.x2 && pos.z > CITY.z1 && pos.z < CITY.z2;
  }

  getZone(pos) {
    if (this.isInsideWalls(pos)) {
      const dw = Math.min(Math.abs(pos.x - CITY.x1), Math.abs(pos.x - CITY.x2), Math.abs(pos.z - CITY.z1), Math.abs(pos.z - CITY.z2));
      if (dw < 18) return ZONES[1];
      return ZONES[0];
    }
    const dw = Math.min(
      Math.abs(pos.x - CITY.x1), Math.abs(pos.x - CITY.x2),
      Math.abs(pos.z - CITY.z1), Math.abs(pos.z - CITY.z2)
    );
    if (dw < 30) return ZONES[1];
    if (pos.x > -20 && pos.z < -195) return ZONES[2];
    if (pos.x < -235) return ZONES[4];
    return ZONES[3];
  }

  spawnPoint(zoneKey, playerPos, minDist = 55) {
    for (let i = 0; i < 40; i++) {
      let x, z;
      if (zoneKey === 'city') { x = rand(-180, 180); z = rand(-150, 150); }
      else if (zoneKey === 'forest') { x = rand(10, 520); z = rand(-560, -230); }
      else if (zoneKey === 'waste') { x = rand(-580, -250); z = rand(-520, 520); }
      else if (zoneKey === 'walls') { x = rand(-80, 80); z = rand(210, 310); }
      else { x = rand(250, 560); z = rand(-150, 540); }
      if (!playerPos || Math.hypot(x - playerPos.x, z - playerPos.z) > minDist) return new THREE.Vector3(x, 0, z);
    }
    return new THREE.Vector3(rand(-200, 200), 0, rand(220, 300));
  }

  damageGate(n) {
    if (!this.gate?.alive) return;
    this.gate.hp = Math.max(0, this.gate.hp - n);
    if (this.gate.hp <= 0) this.breakGate();
  }

  breakGate() {
    if (!this.gate?.alive) return;
    this.gate.alive = false;
    this.gate.group.visible = false;
    this.colliders = this.colliders.filter(c => c !== this.gate.collider);
    this.gate.hp = 0;
  }

  dispose() {
    this.scene.traverse(o => {
      if (o === this.scene) return;
      if (o.isMesh || o.isPoints || o.isSprite) {
        if (o.geometry) o.geometry.dispose?.();
        const mats = Array.isArray(o.material) ? o.material : [o.material];
        for (const m of mats) { if (m?.map) m.map.dispose?.(); m?.dispose?.(); }
      }
    });
    // clear only world-ish children (scene also holds entities, caller handles)
    while (this.scene.children.length) this.scene.remove(this.scene.children[0]);
    this.colliders = []; this.anchors = []; this.trees = []; this.clouds = [];
  }
}

import * as THREE from '../vendor/three/three.module.min.js';
import { rand } from './config.js';

function makeSlashTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 256;
  const ctx = c.getContext('2d');
  const g = ctx.createLinearGradient(0, 0, 256, 0);
  g.addColorStop(0, 'rgba(255,255,255,0)');
  g.addColorStop(.35, 'rgba(255,255,255,.9)');
  g.addColorStop(.65, 'rgba(255,255,255,.95)');
  g.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.strokeStyle = g;
  ctx.lineWidth = 9;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(128, 210, 112, Math.PI * 1.13, Math.PI * 1.87);
  ctx.stroke();
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(255,220,190,.85)';
  ctx.beginPath();
  ctx.arc(128, 210, 100, Math.PI * 1.15, Math.PI * 1.85);
  ctx.stroke();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

const VERT = `
attribute float size;
attribute vec3 color;
varying vec3 vColor;
varying float vAlpha;
attribute float alpha;
void main(){
  vColor = color; vAlpha = alpha;
  vec4 mv = modelViewMatrix * vec4(position,1.0);
  gl_PointSize = size * (260.0 / max(1.0,-mv.z));
  gl_Position = projectionMatrix * mv;
}`;
const FRAG = `
varying vec3 vColor; varying float vAlpha;
void main(){
  vec2 d = gl_PointCoord - vec2(0.5);
  float r = length(d);
  if(r > 0.5) discard;
  float a = smoothstep(0.5,0.05,r) * vAlpha;
  gl_FragColor = vec4(vColor, a);
}`;

export class Effects {
  constructor(scene, camera, damageLayer) {
    this.scene = scene;
    this.camera = camera;
    this.layer = damageLayer;
    this.max = 900;
    this.particles = [];
    const geo = new THREE.BufferGeometry();
    this.posArr = new Float32Array(this.max * 3);
    this.colArr = new Float32Array(this.max * 3);
    this.sizeArr = new Float32Array(this.max);
    this.alphaArr = new Float32Array(this.max);
    geo.setAttribute('position', new THREE.BufferAttribute(this.posArr, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.colArr, 3));
    geo.setAttribute('size', new THREE.BufferAttribute(this.sizeArr, 1));
    geo.setAttribute('alpha', new THREE.BufferAttribute(this.alphaArr, 1));
    geo.setDrawRange(0, 0);
    const mat = new THREE.ShaderMaterial({
      vertexShader: VERT, fragmentShader: FRAG, transparent: true, depthWrite: false,
      blending: THREE.NormalBlending, vertexColors: true
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 3;
    scene.add(this.points);
    this.geo = geo;

    this.lineGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
    this.line = new THREE.Line(this.lineGeo, new THREE.LineBasicMaterial({
      color: 0xdce9f2, transparent: true, opacity: 0.85, depthWrite: false
    }));
    this.line.visible = false;
    this.line.frustumCulled = false;
    scene.add(this.line);

    this.slashTex = makeSlashTexture();
    this.slashes = [];
    for (let i = 0; i < 8; i++) {
      const m = new THREE.SpriteMaterial({
        map: this.slashTex, color: 0xffffff, transparent: true, opacity: 0,
        blending: THREE.AdditiveBlending, depthWrite: false, depthTest: true
      });
      const sp = new THREE.Sprite(m);
      sp.visible = false;
      scene.add(sp);
      this.slashes.push({ sprite: sp, life: 0, max: 0.22, scale: 1 });
    }

    this.numbers = [];
    for (let i = 0; i < 26; i++) {
      const el = document.createElement('div');
      el.className = 'dmg-num';
      el.style.display = 'none';
      damageLayer.appendChild(el);
      this.numbers.push({ el, life: 0, pos: new THREE.Vector3(), active: false });
    }
    this.tmp = new THREE.Vector3();
  }

  addParticle(x, y, z, vx, vy, vz, color, size, life, gravity = 0) {
    if (this.particles.length >= this.max) this.particles.shift();
    this.particles.push({
      x, y, z, vx, vy, vz,
      r: color.r, g: color.g, b: color.b,
      size, life, max: life, gravity
    });
  }

  burst(pos, colorHex, count = 12, speed = 5, size = 0.28, life = 0.7, gravity = -9) {
    const c = new THREE.Color(colorHex);
    for (let i = 0; i < count; i++) {
      const a = rand(0, Math.PI * 2), b = rand(-1, 1);
      const s = rand(speed * 0.25, speed);
      this.addParticle(
        pos.x + rand(-.25, .25), pos.y + rand(-.2, .4), pos.z + rand(-.25, .25),
        Math.cos(a) * Math.sqrt(1 - b * b) * s, b * s + speed * .22, Math.sin(a) * Math.sqrt(1 - b * b) * s,
        c, rand(size * .5, size * 1.5), rand(life * .5, life), gravity
      );
    }
  }

  steam(pos, count = 18, big = 1) {
    for (let i = 0; i < count; i++) {
      const c = new THREE.Color(Math.random() < .5 ? 0xe8e2d8 : 0xbdb6ac);
      this.addParticle(
        pos.x + rand(-big, big), pos.y + rand(0, big * 2), pos.z + rand(-big, big),
        rand(-1.2, 1.2), rand(1.2, 4.5), rand(-1.2, 1.2),
        c, rand(0.8, 2.4) * big, rand(1.2, 2.8), -0.6
      );
    }
  }

  dust(pos, count = 8, colorHex = 0xc9b28c) {
    const c = new THREE.Color(colorHex);
    for (let i = 0; i < count; i++) {
      this.addParticle(
        pos.x + rand(-1, 1), pos.y + rand(0, .3), pos.z + rand(-1, 1),
        rand(-2, 2), rand(.2, 1.8), rand(-2, 2),
        c, rand(.5, 1.6), rand(.6, 1.4), -1
      );
    }
  }

  sparks(pos, count = 10, colorHex = 0xffd27a) {
    const c = new THREE.Color(colorHex);
    for (let i = 0; i < count; i++) {
      this.addParticle(
        pos.x, pos.y, pos.z,
        rand(-7, 7), rand(-2, 8), rand(-7, 7),
        c, rand(.12, .35), rand(.2, .55), -14
      );
    }
  }

  slash(pos, scale = 5, colorHex = 0xffffff, flip = false) {
    const s = this.slashes.find(x => x.life <= 0) || this.slashes[0];
    s.life = s.max = 0.2;
    s.scale = scale;
    s.sprite.visible = true;
    s.sprite.position.copy(pos);
    s.sprite.material.color.setHex(colorHex);
    s.sprite.material.rotation = flip ? rand(-2.6, -1.2) : rand(-.8, .8);
    s.sprite.scale.set(scale, scale, 1);
  }

  number(pos, text, cls = '') {
    const n = this.numbers.find(x => !x.active) || this.numbers[0];
    n.active = true;
    n.life = 0.9;
    n.max = 0.9;
    n.pos.copy(pos);
    n.el.className = 'dmg-num ' + cls;
    n.el.textContent = text;
    n.el.style.display = 'block';
  }

  setLine(a, b) {
    if (!a || !b) { this.line.visible = false; return; }
    const arr = this.lineGeo.attributes.position.array;
    arr[0] = a.x; arr[1] = a.y; arr[2] = a.z;
    arr[3] = b.x; arr[4] = b.y; arr[5] = b.z;
    this.lineGeo.attributes.position.needsUpdate = true;
    this.line.visible = true;
  }

  hideLine() { this.line.visible = false; }

  update(dt) {
    // particles
    let n = 0;
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) { this.particles.splice(i, 1); continue; }
      p.vy += p.gravity * dt;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt;
      p.vx *= 0.985; p.vz *= 0.985;
    }
    for (let i = 0; i < this.particles.length && n < this.max; i++, n++) {
      const p = this.particles[i];
      const a = Math.max(0, p.life / p.max);
      this.posArr[n * 3] = p.x; this.posArr[n * 3 + 1] = p.y; this.posArr[n * 3 + 2] = p.z;
      this.colArr[n * 3] = p.r; this.colArr[n * 3 + 1] = p.g; this.colArr[n * 3 + 2] = p.b;
      this.sizeArr[n] = p.size;
      this.alphaArr[n] = a;
    }
    this.geo.setDrawRange(0, n);
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
    this.geo.attributes.size.needsUpdate = true;
    this.geo.attributes.alpha.needsUpdate = true;

    // slash sprites
    for (const s of this.slashes) {
      if (s.life <= 0) continue;
      s.life -= dt;
      const k = Math.max(0, s.life / s.max);
      s.sprite.material.opacity = k * 0.95;
      const sc = s.scale * (1.3 - k * 0.3);
      s.sprite.scale.set(sc, sc, 1);
      if (s.life <= 0) s.sprite.visible = false;
    }

    // numbers
    const w = innerWidth, h = innerHeight;
    for (const num of this.numbers) {
      if (!num.active) continue;
      num.life -= dt;
      if (num.life <= 0) { num.active = false; num.el.style.display = 'none'; continue; }
      this.tmp.copy(num.pos).project(this.camera);
      if (this.tmp.z > 1) { num.el.style.display = 'none'; continue; }
      num.el.style.display = 'block';
      num.el.style.left = ((this.tmp.x * .5 + .5) * w) + 'px';
      num.el.style.top = ((-this.tmp.y * .5 + .5) * h - (1 - num.life / num.max) * 40) + 'px';
      num.el.style.opacity = Math.min(1, num.life / num.max * 2.2);
    }
  }
}

import * as THREE from '../vendor/three/three.module.min.js';
import { rand } from './config.js';

const skinMats = new Map();
function lambert(color) {
  if (!skinMats.has(color)) skinMats.set(color, new THREE.MeshLambertMaterial({ color }));
  return skinMats.get(color);
}
function std(color, rough = .8, metal = 0) {
  return new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal });
}

function limb(rTop, rBottom, len, mat) {
  const geo = new THREE.CapsuleGeometry((rTop + rBottom) / 2, len, 3, 6);
  const m = new THREE.Mesh(geo, mat);
  m.position.y = -len / 2;
  m.castShadow = true;
  return m;
}

export function createTitanModel(type) {
  const group = new THREE.Group();
  const H = 4.4;
  const skin = new THREE.MeshLambertMaterial({ color: type.color });
  const hair = new THREE.MeshLambertMaterial({ color: type.hair });
  const cloth = new THREE.MeshLambertMaterial({ color: 0x5b4a3a });
  const dark = new THREE.MeshLambertMaterial({ color: 0x1b1512 });
  const tooth = new THREE.MeshLambertMaterial({ color: 0xd8cfb5 });
  const parts = { arms: [], legs: [], lowerArms: [], lowerLegs: [] };
  const mats = [skin, hair, cloth, dark];

  const torso = new THREE.Mesh(new THREE.BoxGeometry(1.34, 1.62, 0.78), skin);
  torso.position.y = 2.64; torso.castShadow = true;
  group.add(torso);
  const belly = new THREE.Mesh(new THREE.SphereGeometry(0.62, 8, 6), skin);
  belly.position.set(0, 2.12, 0.06); belly.scale.set(1.06, .62, .86);
  group.add(belly);
  const hip = new THREE.Mesh(new THREE.BoxGeometry(1.08, 0.5, 0.66), cloth);
  hip.position.y = 1.88; group.add(hip);

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(.26, .34, .3, 6), skin);
  neck.position.y = 3.47; group.add(neck);
  const head = new THREE.Mesh(new THREE.SphereGeometry(.46, 9, 7), skin);
  head.position.y = 3.83; head.scale.set(.94, 1.05, .96); head.castShadow = true;
  group.add(head);
  const hairCap = new THREE.Mesh(new THREE.SphereGeometry(.48, 8, 6, 0, Math.PI * 2, 0, Math.PI * .58), hair);
  hairCap.position.y = 3.9; hairCap.scale.set(1.02, 1.05, 1.02);
  group.add(hairCap);
  // eyes
  const eyeGeo = new THREE.SphereGeometry(.055, 5, 4);
  const e1 = new THREE.Mesh(eyeGeo, dark); e1.position.set(-.15, 3.9, .42); group.add(e1);
  const e2 = new THREE.Mesh(eyeGeo, dark); e2.position.set(.15, 3.9, .42); group.add(e2);
  // mouth
  const mouth = new THREE.Mesh(new THREE.BoxGeometry(.4, .13, .06), dark);
  mouth.position.set(0, 3.68, .43); group.add(mouth);
  const teeth = new THREE.Mesh(new THREE.BoxGeometry(.34, .04, .02), tooth);
  teeth.position.set(0, 3.73, .46); group.add(teeth);

  // nape weak point (behind neck)
  const nape = new THREE.Mesh(new THREE.SphereGeometry(.14, 7, 5), new THREE.MeshBasicMaterial({ color: 0xff5b3a }));
  nape.position.set(0, 3.48, -.34);
  group.add(nape);
  parts.nape = nape;
  const halo = new THREE.Sprite(new THREE.SpriteMaterial({
    color: 0xff6b45, transparent: true, opacity: .55, depthWrite: false,
    blending: THREE.AdditiveBlending
  }));
  halo.scale.set(1.1, 1.1, 1);
  halo.position.copy(nape.position);
  group.add(halo);
  parts.napeHalo = halo;

  // arms
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * .82, 3.24, 0);
    const upper = limb(.19, .15, 1.12, skin);
    shoulder.add(upper);
    const elbow = new THREE.Group();
    elbow.position.y = -1.08;
    const lower = limb(.14, .11, 1.08, skin);
    elbow.add(lower);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(.16, 6, 5), skin);
    hand.position.y = -1.08; elbow.add(hand);
    shoulder.add(elbow);
    group.add(shoulder);
    parts.arms.push(shoulder);
    parts.lowerArms.push(elbow);
    if (type.key === 'aberrant') { shoulder.rotation.z = side * 0.14; }
  }

  // legs
  for (const side of [-1, 1]) {
    const hipJ = new THREE.Group();
    hipJ.position.set(side * .36, 1.84, 0);
    const upper = limb(.24, .19, 1.0, skin);
    hipJ.add(upper);
    const knee = new THREE.Group();
    knee.position.y = -0.98;
    const lower = limb(.18, .14, .9, skin);
    knee.add(lower);
    const foot = new THREE.Mesh(new THREE.BoxGeometry(.34, .2, .58), skin);
    foot.position.set(0, -.95, .14); knee.add(foot);
    hipJ.add(knee);
    group.add(hipJ);
    parts.legs.push(hipJ);
    parts.lowerLegs.push(knee);
  }

  if (type.key === 'armored') {
    const armorMat = new THREE.MeshStandardMaterial({ color: 0x7b7f7e, roughness: .55, metalness: .45 });
    const chest = new THREE.Mesh(new THREE.BoxGeometry(1.46, .9, .9), armorMat);
    chest.position.set(0, 3.0, 0); group.add(chest);
    const plates = [
      [0, 2.42, .44, 1.1, .34, .1], [0, 2.05, .48, .9, .2, .08],
      [-.86, 3.12, .1, .42, .26, .72], [.86, 3.12, .1, .42, .26, .72],
      [-.36, 1.42, .12, .38, .34, .42], [.36, 1.42, .12, .38, .34, .42]
    ];
    for (const p of plates) {
      const m = new THREE.Mesh(new THREE.BoxGeometry(p[3], p[4], p[5]), armorMat);
      m.position.set(p[0], p[1], p[2]); group.add(m);
    }
    const helm = new THREE.Mesh(new THREE.BoxGeometry(.66, .34, .52), armorMat);
    helm.position.set(0, 4.2, 0); group.add(helm);
  }
  if (type.key === 'colossal') {
    const muscle = new THREE.MeshLambertMaterial({ color: 0x8f3327, emissive: 0x3a0d07, emissiveIntensity: 1 });
    for (const side of [-1, 1]) {
      const strip = new THREE.Mesh(new THREE.BoxGeometry(.14, 1.3, .1), muscle);
      strip.position.set(side * .28, 2.7, .43); group.add(strip);
    }
    const glow = new THREE.PointLight(0xff5522, 1.2, 22, 2);
    glow.position.set(0, 4, 0); group.add(glow);
    parts.glow = glow;
  }
  if (type.key === 'dummy') {
    // straw dummy look with a target on the chest
    const targetMat = new THREE.MeshBasicMaterial({ color: 0xe8dcc0 });
    for (const r of [.52, .34, .16]) {
      const ring = new THREE.Mesh(new THREE.RingGeometry(r - .05, r, 16), targetMat);
      ring.position.set(0, 2.7, .44); group.add(ring);
    }
    const post = new THREE.Mesh(new THREE.CylinderGeometry(.16, .2, 1.4, 5), new THREE.MeshLambertMaterial({ color: 0x6c5236 }));
    post.position.set(0, .7, 0); group.add(post);
  }

  group.scale.setScalar(type.height / H);
  parts.group = group;
  parts.torso = torso;
  parts.head = head;
  parts.skin = skin;
  parts.mats = mats;
  parts.baseHeight = H;
  return parts;
}

