      this.yaw += this.angleTo(this.yaw, dy) * Math.min(1, dt * 5);
    }
    this.group.rotation.y = this.yaw;
    this.group.rotation.z = this.hook.active ? clamp(-this.vel.x * .004, -.28, .28) : 0;

